@import "tailwindcss";
@import "@fontsource-variable/roboto";

@custom-variant dark (&:where(.dark, .dark *));

:root {
  --bg: #f6f8fc;
  --panel: #ffffff;
  --raised: #ffffff;
  --fg: #1f1f1f;
  --fg2: #444746;
  --fg3: #5f6368;
  --line: #e3e5e8;
  --line-strong: #c4c7c5;
  --hover: rgba(68, 71, 70, 0.08);
  --press: rgba(68, 71, 70, 0.14);
  --nav-active: #d3e3fd;
  --nav-active-fg: #041e49;
  --compose: #c2e7ff;
  --compose-fg: #001d35;
  --search: #e9eef6;
  --search-focus: #ffffff;
  --row-read: #f2f6fc;
  --row-unread: #ffffff;
  --row-selected: #c2dbff;
  --accent: #0b57d0;
  --accent-fg: #ffffff;
  --accent-soft: #d3e3fd;
  --accent-text: #0b57d0;
  --chip: #f1f3f4;
  --danger: #d93025;
  --success: #188038;
  --star: #f4b400;
  --toast: #323232;
  --scrim: rgba(32, 33, 36, 0.4);
  --quote: #5f6368;
  --shadow-1: 0 1px 2px 0 rgba(60, 64, 67, 0.3), 0 1px 3px 1px rgba(60, 64, 67, 0.15);
  --shadow-2: 0 1px 3px 0 rgba(60, 64, 67, 0.3), 0 4px 8px 3px rgba(60, 64, 67, 0.15);
  --shadow-row: inset 1px 0 0 #dadce0, inset -1px 0 0 #dadce0, 0 1px 2px 0 rgba(60, 64, 67, 0.3), 0 1px 3px 1px rgba(60, 64, 67, 0.15);
  color-scheme: light;
}

.dark {
  --bg: #111214;
  --panel: #1c1d20;
  --raised: #2a2b2f;
  --fg: #e3e3e3;
  --fg2: #c4c7c5;
  --fg3: #9aa0a6;
  --line: #34363a;
  --line-strong: #4a4d52;
  --hover: rgba(227, 227, 227, 0.08);
  --press: rgba(227, 227, 227, 0.14);
  --nav-active: #004a77;
  --nav-active-fg: #c2e7ff;
  --compose: #004a77;
  --compose-fg: #c2e7ff;
  --search: #2a2b2f;
  --search-focus: #35363b;
  --row-read: #1c1d20;
  --row-unread: #26282c;
  --row-selected: #253a5a;
  --accent: #a8c7fa;
  --accent-fg: #062e6f;
  --accent-soft: #0f3a6e;
  --accent-text: #a8c7fa;
  --chip: #2f3034;
  --danger: #f28b82;
  --success: #81c995;
  --star: #fdd663;
  --toast: #e3e3e3;
  --scrim: rgba(0, 0, 0, 0.6);
  --quote: #9aa0a6;
  --shadow-1: 0 1px 2px 0 rgba(0, 0, 0, 0.6), 0 1px 3px 1px rgba(0, 0, 0, 0.3);
  --shadow-2: 0 2px 6px 0 rgba(0, 0, 0, 0.6), 0 6px 14px 4px rgba(0, 0, 0, 0.35);
  --shadow-row: inset 1px 0 0 #3c4043, inset -1px 0 0 #3c4043, 0 1px 3px 0 rgba(0, 0, 0, 0.6);
  color-scheme: dark;
}

@theme inline {
  --font-sans: "Roboto Variable", "Roboto", ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif;
  --color-bg: var(--bg);
  --color-panel: var(--panel);
  --color-raised: var(--raised);
  --color-fg: var(--fg);
  --color-fg2: var(--fg2);
  --color-fg3: var(--fg3);
  --color-line: var(--line);
  --color-line-strong: var(--line-strong);
  --color-hover: var(--hover);
  --color-press: var(--press);
  --color-nav-active: var(--nav-active);
  --color-nav-active-fg: var(--nav-active-fg);
  --color-compose: var(--compose);
  --color-compose-fg: var(--compose-fg);
  --color-search: var(--search);
  --color-search-focus: var(--search-focus);
  --color-row-read: var(--row-read);
  --color-row-unread: var(--row-unread);
  --color-row-selected: var(--row-selected);
  --color-accent: var(--accent);
  --color-accent-fg: var(--accent-fg);
  --color-accent-soft: var(--accent-soft);
  --color-accent-text: var(--accent-text);
  --color-chip: var(--chip);
  --color-danger: var(--danger);
  --color-success: var(--success);
  --color-star: var(--star);
  --color-toast: var(--toast);
  --color-scrim: var(--scrim);
  --shadow-e1: var(--shadow-1);
  --shadow-e2: var(--shadow-2);
  --shadow-row: var(--shadow-row);
  --animate-pop: pop 140ms cubic-bezier(0.2, 0, 0, 1);
  --animate-fade: fade 160ms ease-out;
  --animate-slide-up: slide-up 220ms cubic-bezier(0.2, 0, 0, 1);
  --animate-slide-left: slide-left 220ms cubic-bezier(0.2, 0, 0, 1);
  --animate-slide-right: slide-right 240ms cubic-bezier(0.2, 0, 0, 1);
}

@keyframes pop {
  from { opacity: 0; transform: scale(0.96) translateY(-4px); }
  to { opacity: 1; transform: none; }
}
@keyframes fade {
  from { opacity: 0; }
  to { opacity: 1; }
}
@keyframes slide-up {
  from { opacity: 0; transform: translateY(16px); }
  to { opacity: 1; transform: none; }
}
@keyframes slide-left {
  from { transform: translateX(100%); }
  to { transform: none; }
}
@keyframes slide-right {
  from { transform: translateX(-100%); }
  to { transform: none; }
}
@keyframes spin {
  to { transform: rotate(360deg); }
}
@keyframes arrive {
  from { background-color: var(--accent-soft); }
}

html,
body,
#root {
  height: 100%;
}

body {
  margin: 0;
  background: var(--bg);
  color: var(--fg);
  font-family: var(--font-sans);
  font-size: 14px;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  overscroll-behavior: none;
}

button {
  cursor: pointer;
}

button:disabled {
  cursor: default;
}

:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: -2px;
}

* {
  scrollbar-width: thin;
  scrollbar-color: var(--line-strong) transparent;
}

::selection {
  background: #c2dbff;
}

.dark ::selection {
  background: #3b5998;
}

.row-arrive {
  animation: arrive 2.4s ease-out;
}

/* Message bodies */
.mail-body {
  font-size: 14px;
  line-height: 1.55;
  color: var(--fg);
  overflow-wrap: anywhere;
}
.mail-body p {
  margin: 0 0 0.85em;
}
.mail-body p:last-child {
  margin-bottom: 0;
}
.mail-body a {
  color: var(--accent-text);
}
.mail-body ul,
.mail-body ol {
  margin: 0 0 0.85em;
  padding-left: 1.6em;
}
.mail-body ul {
  list-style: disc;
}
.mail-body ol {
  list-style: decimal;
}
.mail-body li {
  margin: 0.15em 0;
}
.mail-body blockquote {
  margin: 0.5em 0 0.5em 0.4em;
  padding-left: 0.9em;
  border-left: 2px solid var(--line-strong);
  color: var(--quote);
}
.mail-body pre,
.mail-body code {
  font-family: ui-monospace, "SF Mono", Menlo, monospace;
  font-size: 12.5px;
}
.mail-body pre {
  background: var(--chip);
  border-radius: 8px;
  padding: 10px 12px;
  overflow-x: auto;
  margin: 0 0 0.85em;
}
.mail-body code {
  background: var(--chip);
  padding: 1px 4px;
  border-radius: 4px;
}
.mail-body pre code {
  background: none;
  padding: 0;
}
.mail-body h1,
.mail-body h2,
.mail-body h3 {
  font-weight: 500;
  margin: 0 0 0.5em;
}
.mail-body table {
  border-collapse: collapse;
}
.mail-body img {
  max-width: 100%;
}
.mail-body .signature {
  color: var(--fg3);
}
.mail-body mark,
.mail-hl {
  background: #fde293;
  color: #1f1f1f;
  border-radius: 2px;
}
.mail-body .html-email {
  color: #1f1f1f;
}

/* Rich editor */
.editor {
  outline: none;
  line-height: 1.5;
  overflow-wrap: anywhere;
}
.editor:empty::before {
  content: attr(data-placeholder);
  color: var(--fg3);
  pointer-events: none;
}
.editor p {
  margin: 0;
}
.editor ul {
  list-style: disc;
  padding-left: 1.6em;
}
.editor ol {
  list-style: decimal;
  padding-left: 1.6em;
}
.editor blockquote {
  margin: 0 0 0 0.4em;
  padding-left: 0.9em;
  border-left: 2px solid var(--line-strong);
  color: var(--quote);
}
.editor a {
  color: var(--accent-text);
  text-decoration: underline;
}
.editor .signature {
  color: var(--fg3);
}

.no-scrollbar {
  scrollbar-width: none;
}
.no-scrollbar::-webkit-scrollbar {
  display: none;
}

@media print {
  body {
    background: #fff;
  }
  .print-hide {
    display: none !important;
  }
  .print-only-thread {
    position: static !important;
    overflow: visible !important;
    height: auto !important;
  }
}

