  name: string;
  email: string;
}

export interface Contact extends Person {
  kind: 'person' | 'org';
  title?: string;
  org?: string;
  phone?: string;
}

export interface Attachment {
  id: string;
  name: string;
  size: number;
  type: string;
  preview?: string;
  dataUrl?: string;
}

export type MessageStatus = 'received' | 'sent' | 'draft' | 'scheduled';

export interface Message {
  id: string;
  threadId: string;
