    ${bars.map((b, i) => `<rect x="${60 + i * 78}" y="${360 - b * 0.7}" width="44" height="${b * 0.7}" rx="6" fill="${accent}" opacity="${0.45 + i * 0.08}"/>`).join('')}`,
