    <path d="M0 330 C120 290 220 350 330 320 S520 290 640 330 V420 H0Z" fill="${hill2}"/>
    <path d="M0 370 C160 350 300 390 640 360 V420 H0Z" fill="#000" opacity=".18"/>`,
  );
}

