                <Hl text={t.subject || '(no subject)'} terms={p.highlight} />
              </span>
            </div>
            <div className="flex items-start gap-2">
              <span className="line-clamp-2 min-w-0 flex-1 text-sm text-fg3">
                <Hl text={snip || '(no content)'} terms={p.highlight} />
