                }}
                className={cn('-mt-1 -mr-1 flex size-8 shrink-0 items-center justify-center rounded-full hover:bg-hover', t.starred ? 'text-star' : 'text-fg3')}
              >
                {t.starred ? <MdStar size={20} /> : <MdStarBorder size={20} />}
