  return (
    <>
      <MenuItem
        icon={MdSchedule}
        label="Schedule send"
        onClick={() => {
          setOpen(true);
        }}
      />
      <ScheduleDialog
        open={open}
        onClose={() => {
          setOpen(false);
          close();
