  MdArrowDropDown,
  MdAttachFile,
  MdClose,
  MdCloseFullscreen,
  MdDateRange,
  MdForward,
  MdInsertLink,
  MdMinimize,
  MdMoreHoriz,
  MdMoreVert,
  MdOpenInFull,
  MdOpenInNew,
  MdOutlineDelete,
  MdOutlineEmojiEmotions,
  MdReply,
  MdReplyAll,
  MdSchedule,
  MdSend,
  MdTextFormat,
} from 'react-icons/md';
import type { Attachment, ComposeMode, DraftFields } from '../../types';
import { useIsMobile } from '../../hooks';
import { replyFields } from '../../lib/compose';
import { closeWindow, me, popOutInline, reopenWindow, saveDraftNow, sendDraft, updateWindow } from '../../lib/composeActions';
import { formatFuture, schedulePresets } from '../../lib/date';
import { currentRoute } from '../../lib/router';
