interface ComposerParams {
  threadId: string;
  draftId: string;
  mode: ComposeMode;
  initial: DraftFields;
  onClosed: () => void;
  reopen: (fields: DraftFields, mode: ComposeMode) => void;
}

const MAX_INLINE_BYTES = 700 * 1024;

function useComposer(p: ComposerParams) {
  const [fields, setFields] = useState<DraftFields>(p.initial);
  const [mode, setMode] = useState<ComposeMode>(p.mode);
  const [status, setStatus] = useState<'idle' | 'saving' | 'saved'>(p.initial.body && useMail.getState().threads[p.threadId]?.messages.some((m) => m.id === p.draftId) ? 'saved' : 'idle');
  const [uploading, setUploading] = useState<string[]>([]);
  const fieldsRef = useRef(fields);
  fieldsRef.current = fields;
  const modeRef = useRef(mode);
  modeRef.current = mode;
  const closed = useRef(false);
  const first = useRef(true);

  useEffect(() => {
    if (first.current) {
      first.current = false;
      return;
    }
    setStatus('saving');
    const id = setTimeout(() => {
      if (closed.current) return;
      const saved = saveDraftNow(p.threadId, p.draftId, fieldsRef.current, modeRef.current);
      setStatus(saved ? 'saved' : 'idle');
    }, 800);
    return () => clearTimeout(id);
  }, [fields, p.threadId, p.draftId]);

  useEffect(
    () => () => {
      if (!closed.current) saveDraftNow(p.threadId, p.draftId, fieldsRef.current, modeRef.current);
    },
    [p.threadId, p.draftId],
  );

  const update = (patch: Partial<DraftFields>) => setFields((f) => ({ ...f, ...patch }));

  const close = () => {
    closed.current = true;
    saveDraftNow(p.threadId, p.draftId, fieldsRef.current, modeRef.current);
    p.onClosed();
  };

  const discard = () => {
    closed.current = true;
    const snap = useMail.getState().snapshot([p.threadId]);
    const f = fieldsRef.current;
    const m = modeRef.current;
    useMail.getState().discardDraft(p.threadId, p.draftId);
    p.onClosed();
    showToast('Draft discarded.', {
      undo: () => {
        useMail.getState().restore(snap);
        p.reopen(f, m);
      },
    });
  };

  const addFiles = async (files: File[]) => {
    const atts: Attachment[] = await Promise.all(
      files.map(
        (file) =>
          new Promise<Attachment>((resolve) => {
            const base: Attachment = { id: uid('att'), name: file.name, size: file.size, type: file.type || 'application/octet-stream' };
            if (file.size > MAX_INLINE_BYTES) return resolve(base);
            const reader = new FileReader();
            reader.onload = () => resolve({ ...base, dataUrl: reader.result as string });
            reader.onerror = () => resolve(base);
            reader.readAsDataURL(file);
          }),
      ),
    );
    setUploading((u) => [...u, ...atts.map((a) => a.id)]);
    setFields((f) => ({ ...f, attachments: [...f.attachments, ...atts] }));
    atts.forEach((a, i) => setTimeout(() => setUploading((u) => u.filter((x) => x !== a.id)), 500 + i * 250 + Math.min(1200, a.size / 20000)));
  };

  const doSend = (scheduledAt?: number) => {
    const f = fieldsRef.current;
    const final: DraftFields = { ...f, body: sanitizeHtml(f.body) };
    closed.current = true;
    const m = modeRef.current;
    sendDraft({ threadId: p.threadId, draftId: p.draftId, fields: final, mode: m, scheduledAt, reopen: () => p.reopen(final, m) });
    p.onClosed();
  };

  const send = (scheduledAt?: number) => {
    const f = fieldsRef.current;
    if (uploading.length) {
      showToast('Please wait for attachments to finish uploading.');
      return;
    }
    const all = [...f.to, ...f.cc, ...f.bcc];
    if (!all.length) {
      confirmDialog({ title: 'Error', message: 'Please specify at least one recipient.', confirmLabel: 'OK', alertOnly: true, onConfirm: () => {} });
      return;
    }
    const bad = all.find((x) => !isValidEmail(x.email));
    if (bad) {
      confirmDialog({
        title: 'Error',
        message: `The address "${bad.email}" was not recognized. Please make sure that all addresses are properly formed.`,
        confirmLabel: 'OK',
        alertOnly: true,
        onConfirm: () => {},
      });
      return;
    }
    const bodyText = htmlToText(f.body.replace(/<div class="(signature|forwarded)">[\s\S]*$/, ''));
    const checks: Array<() => boolean> = [];
    const proceed = (i: number) => {
      if (i >= checks.length) return doSend(scheduledAt);
      if (checks[i]()) proceed(i + 1);
    };
    checks.push(() => {
      if (f.subject.trim()) return true;
      confirmDialog({
        message: bodyText ? 'Send this message without a subject?' : 'Send this message without a subject or text in the body?',
        confirmLabel: 'OK',
        onConfirm: () => proceed(1),
      });
      return false;
    });
    checks.push(() => {
      if (f.attachments.length || !/\b(attached|attachment|attaching|enclosed)\b/i.test(bodyText)) return true;
      confirmDialog({
        title: 'Did you mean to attach files?',
        message: 'You wrote “attached” in your message, but there are no files attached. Send anyway?',
        confirmLabel: 'Send',
        onConfirm: () => proceed(2),
      });
      return false;
    });
    proceed(0);
  };

  const switchMode = (next: ComposeMode) => {
    const t = useMail.getState().threads[p.threadId];
    if (!t || next === mode) return;
    const sig = useSettings.getState().signature;
    const r = replyFields(t, next, MY_EMAIL, sig);
    setMode(next);
    setFields((f) => ({
      ...f,
      to: r.to,
      cc: r.cc,
      subject: r.subject,
      quote: r.quote,
      attachments: next === 'forward' ? r.attachments : f.attachments.filter((a) => a.dataUrl),
      body: next === 'forward' && !f.body.includes('Forwarded message') ? r.body : f.body,
    }));
  };

  return { fields, update, mode, switchMode, status, close, discard, send, addFiles, uploading, setUploading };
}

type Composer = ReturnType<typeof useComposer>;

function AttachmentList({ c }: { c: Composer }) {
  if (!c.fields.attachments.length) return null;
  return (
    <div className="flex flex-col gap-1.5 py-2">
      {c.fields.attachments.map((a) => {
        const k = fileKind(a.name, a.type);
        const loading = c.uploading.includes(a.id);
        return (
          <div key={a.id} className="relative flex h-9 max-w-md items-center gap-2 overflow-hidden rounded bg-chip px-3 text-sm">
            <k.icon size={18} style={{ color: k.color }} className="shrink-0" />
            <span className="min-w-0 flex-1 truncate font-medium text-accent-text">{a.name}</span>
            <span className="shrink-0 text-xs text-fg3">({formatSize(a.size)})</span>
            <button
              type="button"
              aria-label={`Remove ${a.name}`}
              onClick={() => c.update({ attachments: c.fields.attachments.filter((x) => x.id !== a.id) })}
              className="flex size-6 items-center justify-center rounded-full text-fg3 hover:bg-hover"
            >
              <MdClose size={16} />
            </button>
            {loading && (
              <span className="absolute inset-x-0 bottom-0 h-0.5 overflow-hidden bg-line" role="progressbar" aria-label={`Uploading ${a.name}`}>
                <span className="block h-full w-1/2 animate-pulse bg-accent" />
              </span>
            )}
          </div>
        );
      })}
    </div>
  );
}

function ScheduleDialog({ open, onClose, onPick }: { open: boolean; onClose: () => void; onPick: (ts: number) => void }) {
  const presets = schedulePresets();
  return (
    <Modal open={open} onClose={onClose} label="Schedule send" className="max-w-sm py-4">
      <h2 className="px-6 pb-2 text-lg text-fg">Schedule send</h2>
      {presets.map((p) => (
        <button
          key={p.id}
          type="button"
          onClick={() => {
            onClose();
            onPick(p.at);
          }}
          className="flex w-full items-center justify-between px-6 py-2.5 text-left text-sm hover:bg-hover"
        >
          <span className="text-fg">{p.label}</span>
          <span className="text-fg3">{p.detail}</span>
        </button>
      ))}
      <div className="my-1 h-px bg-line" />
      <button
        type="button"
        onClick={() => {
          onClose();
          openDateTime({ title: 'Pick date & time', confirmLabel: 'Schedule send', onPick });
        }}
        className="flex w-full items-center gap-3 px-6 py-2.5 text-left text-sm text-fg hover:bg-hover"
      >
        <MdDateRange size={20} className="text-fg2" /> Pick date &amp; time
      </button>
    </Modal>
  );
}

function BottomBar({ c, editor, onPopOut, compact }: { c: Composer; editor: React.RefObject<EditorHandle | null>; onPopOut?: () => void; compact?: boolean }) {
  const [showFormat, setShowFormat] = useState(false);
  const [sendMenu, setSendMenu] = useState<HTMLElement | null>(null);
  const [schedule, setSchedule] = useState(false);
  const [linkAnchor, setLinkAnchor] = useState<HTMLElement | null>(null);
  const [emojiAnchor, setEmojiAnchor] = useState<HTMLElement | null>(null);
  const [linkText, setLinkText] = useState('');
  const fileRef = useRef<HTMLInputElement>(null);
  return (
    <div className="shrink-0">
      {showFormat && (
        <div className="pb-2">
          <FormatBar editor={editor} />
        </div>
      )}
      <div className="flex items-center gap-1">
        <div className="flex h-9 shrink-0 overflow-hidden rounded-full bg-accent text-accent-fg">
          <button type="button" onClick={() => c.send()} className="pr-4 pl-5 text-sm font-medium hover:bg-black/10" data-tip="Send (⌘Enter)">
            Send
          </button>
          <span className="my-2 w-px bg-accent-fg/30" />
          <button type="button" aria-label="More send options" data-tip="More send options" onClick={(e) => setSendMenu(e.currentTarget)} className="px-1.5 hover:bg-black/10">
            <MdArrowDropDown size={20} />
          </button>
        </div>
        <Popover open={!!sendMenu} anchor={sendMenu} onClose={() => setSendMenu(null)} placement="top-start">
          <MenuItem
            icon={MdSchedule}
            label="Schedule send"
            onClick={() => {
              setSendMenu(null);
              setSchedule(true);
            }}
          />
        </Popover>
        <ScheduleDialog open={schedule} onClose={() => setSchedule(false)} onPick={(ts) => c.send(ts)} />
        <div className={cn('ml-1 flex min-w-0 items-center', compact ? 'gap-0' : 'gap-0.5')}>
          <IconButton icon={MdTextFormat} label="Formatting options" size="sm" active={showFormat} onClick={() => setShowFormat((s) => !s)} />
          <IconButton icon={MdAttachFile} label="Attach files" size="sm" onClick={() => fileRef.current?.click()} />
          <input
            ref={fileRef}
            type="file"
            multiple
            hidden
            onChange={(e) => {
              const files = Array.from(e.target.files ?? []);
              if (files.length) c.addFiles(files);
              e.target.value = '';
            }}
          />
          <IconButton
            icon={MdInsertLink}
            label="Insert link"
            size="sm"
            onMouseDown={(e) => {
              e.preventDefault();
              editor.current?.saveSelection();
              setLinkText(window.getSelection()?.toString() ?? '');
            }}
            onClick={(e) => setLinkAnchor(e.currentTarget)}
          />
          <IconButton
            icon={MdOutlineEmojiEmotions}
            label="Insert emoji"
            size="sm"
            onMouseDown={(e) => {
              e.preventDefault();
              editor.current?.saveSelection();
            }}
            onClick={(e) => setEmojiAnchor(e.currentTarget)}
          />
          {onPopOut && <IconButton icon={MdOpenInNew} label="Pop out reply" size="sm" onClick={onPopOut} />}
        </div>
        <Popover open={!!linkAnchor} anchor={linkAnchor} onClose={() => setLinkAnchor(null)} placement="top-start" role="dialog">
          <LinkForm
            initialText={linkText}
            onCancel={() => setLinkAnchor(null)}
            onSubmit={(text, url) => {
              setLinkAnchor(null);
              editor.current?.insertHtml(`<a href="${escapeHtml(url)}">${escapeHtml(text)}</a>&nbsp;`);
            }}
          />
        </Popover>
        <Popover open={!!emojiAnchor} anchor={emojiAnchor} onClose={() => setEmojiAnchor(null)} placement="top-start">
          <EmojiGrid
            onPick={(e) => {
              editor.current?.insertHtml(e);
              editor.current?.saveSelection();
            }}
          />
        </Popover>
        <div className="flex-1" />
        <span className="hidden truncate pr-1 text-xs text-fg3 sm:inline" aria-live="polite">
          {c.status === 'saving' ? 'Saving…' : c.status === 'saved' ? 'Draft saved' : ''}
        </span>
        <IconButton icon={MdOutlineDelete} label="Discard draft" size="sm" onClick={c.discard} />
      </div>
    </div>
  );
}

function useDropFiles(c: Composer) {
  const [over, setOver] = useState(false);
  return {
    over,
    props: {
      onDragOver: (e: React.DragEvent) => {
        if (!e.dataTransfer.types.includes('Files')) return;
        e.preventDefault();
        setOver(true);
      },
      onDragLeave: (e: React.DragEvent) => {
        if (!e.currentTarget.contains(e.relatedTarget as Node)) setOver(false);
      },
      onDrop: (e: React.DragEvent) => {
        if (!e.dataTransfer.files.length) return;
        e.preventDefault();
        setOver(false);
        c.addFiles(Array.from(e.dataTransfer.files));
      },
    },
  };
}

function DropOverlay() {
  return (
    <div className="pointer-events-none absolute inset-0 z-20 flex items-center justify-center rounded-[inherit] border-2 border-dashed border-accent bg-accent-soft/80 text-base font-medium text-fg">
      Drop files here
    </div>
  );
}

function sendShortcut(c: Composer) {
  return (e: React.KeyboardEvent) => {
    if ((e.metaKey || e.ctrlKey) && e.key === 'Enter') {
      e.preventDefault();
      c.send();
    }
  };
}

function reopenAsWindow(win: Omit<ComposeWin, 'id'>) {
  return (fields: DraftFields, mode: ComposeMode) => reopenWindow({ ...win, initial: fields, mode, focus: 'body' });
}

function ComposeWindow({ win, index, total }: { win: ComposeWin; index: number; total: number }) {
  const isMobile = useIsMobile();
  const c = useComposer({
    threadId: win.threadId,
    draftId: win.draftId,
    mode: win.mode,
    initial: win.initial,
    onClosed: () => closeWindow(win.id),
    reopen: reopenAsWindow(win),
  });
  const editor = useRef<EditorHandle>(null);
  const [showCc, setShowCc] = useState(win.initial.cc.length > 0);
  const [showBcc, setShowBcc] = useState(win.initial.bcc.length > 0);
  const [recipientsOpen, setRecipientsOpen] = useState(win.focus === 'to' || !win.initial.to.length);
  const drop = useDropFiles(c);
  const [moreAnchor, setMoreAnchor] = useState<HTMLElement | null>(null);
  const title = c.fields.subject.trim() || (win.mode === 'new' ? 'New Message' : win.mode === 'forward' ? 'Forward' : 'Reply');

  const recipients = recipientsOpen ? (
    <>
      <RecipientField
        label="To"
        value={c.fields.to}
        onChange={(to) => c.update({ to })}
        autoFocus={win.focus === 'to'}
        inputId={`${win.id}-to`}
        trailing={
          <span className="ml-auto flex gap-2 pl-2 text-sm text-fg2">
            {!showCc && (
              <button type="button" className="hover:underline" onClick={() => setShowCc(true)}>
                Cc
              </button>
            )}
            {!showBcc && (
              <button type="button" className="hover:underline" onClick={() => setShowBcc(true)}>
                Bcc
              </button>
            )}
          </span>
        }
      />
      {showCc && <RecipientField label="Cc" value={c.fields.cc} onChange={(cc) => c.update({ cc })} autoFocus={showCc && !win.initial.cc.length} />}
      {showBcc && <RecipientField label="Bcc" value={c.fields.bcc} onChange={(bcc) => c.update({ bcc })} autoFocus={showBcc && !win.initial.bcc.length} />}
    </>
  ) : (
    <button type="button" onClick={() => setRecipientsOpen(true)} className="flex h-10 w-full items-center border-b border-line text-left text-sm">
      <span className="truncate text-fg">{[...c.fields.to, ...c.fields.cc, ...c.fields.bcc].map((x) => x.name || x.email).join(', ') || <span className="text-fg3">Recipients</span>}</span>
    </button>
  );

  const body = (
    <>
      <div className="px-4" onFocus={(e) => e.target instanceof HTMLInputElement && e.target.id?.includes('subject') && setRecipientsOpen(false)}>
        {recipients}
        <input
          id={`${win.id}-subject`}
          value={c.fields.subject}
          onChange={(e) => c.update({ subject: e.target.value })}
          placeholder="Subject"
          aria-label="Subject"
          autoFocus={win.focus === 'subject'}
          onFocus={() => c.fields.to.length && setRecipientsOpen(false)}
          className="h-10 w-full border-b border-line bg-transparent text-sm text-fg outline-none placeholder:text-fg3"
        />
      </div>
      <div className="min-h-0 flex-1 overflow-y-auto px-4 pt-3" onClick={(e) => e.target === e.currentTarget && editor.current?.focus(true)} onFocus={() => c.fields.to.length && setRecipientsOpen(false)}>
        <RichEditor
          ref={editor}
          initialHtml={win.initial.body}
          onChange={(bodyHtml) => c.update({ body: bodyHtml })}
          autoFocus={win.focus === 'body'}
          onKeyDown={sendShortcut(c)}
          onFiles={c.addFiles}
          className="min-h-[160px] pb-4"
        />
        {c.fields.quote && (
          <div className="pb-3">
            <QuoteToggle html={c.fields.quote} />
          </div>
        )}
        <AttachmentList c={c} />
      </div>
    </>
  );

  if (isMobile) {
    return createPortal(
      <div className="fixed inset-0 z-[55] flex animate-slide-up flex-col bg-panel" {...drop.props} role="dialog" aria-label={title} onKeyDown={(e) => e.stopPropagation()}>
        {drop.over && <DropOverlay />}
        <div className="flex h-14 shrink-0 items-center gap-1 px-1">
          <IconButton icon={MdArrowBack} label="Save & close" onClick={c.close} />
          <span className="flex-1 truncate pl-1 text-lg text-fg">{win.mode === 'new' ? 'Compose' : title}</span>
          <IconButton icon={MdAttachFile} label="Attach files" onClick={() => document.getElementById(`${win.id}-file`)?.click()} />
          <input
            id={`${win.id}-file`}
            type="file"
            multiple
            hidden
            onChange={(e) => {
              const files = Array.from(e.target.files ?? []);
              if (files.length) c.addFiles(files);
              e.target.value = '';
            }}
          />
          <IconButton icon={MdSend} label="Send" onClick={() => c.send()} className="text-accent-text" />
          <IconButton icon={MdMoreVert} label="More options" onClick={(e) => setMoreAnchor(e.currentTarget)} />
          <Popover open={!!moreAnchor} anchor={moreAnchor} onClose={() => setMoreAnchor(null)} placement="bottom-end">
            <div className="w-52">
              <MobileScheduleItem c={c} close={() => setMoreAnchor(null)} />
              <MenuItem icon={MdOutlineDelete} label="Discard" onClick={() => { setMoreAnchor(null); c.discard(); }} />
            </div>
          </Popover>
        </div>
        <div className="flex h-10 items-center border-b border-line px-4 text-sm">
          <span className="mr-3 text-fg3">From</span>
          <span className="truncate text-fg">{me().name} &lt;{MY_EMAIL}&gt;</span>
        </div>
        {body}
      </div>,
      document.body,
    );
  }

  const width = win.minimized ? 280 : 540;
  const right = 16 + (total - 1 - index) * (win.minimized ? 296 : 556);
  const style = win.maximized ? undefined : { width, right };

  const panel = (
    <div
      role="dialog"
      aria-label={title}
      {...drop.props}
      onKeyDown={(e) => {
        if (e.key === 'Escape') {
          e.stopPropagation();
          c.close();
        }
      }}
      className={cn(
        'pointer-events-auto relative flex flex-col overflow-hidden bg-raised shadow-e2',
        win.maximized ? 'h-[min(88vh,900px)] w-[min(92vw,1100px)] animate-pop rounded-2xl' : 'fixed bottom-0 animate-slide-up rounded-t-xl',
        !win.maximized && !win.minimized && 'h-[min(600px,calc(100vh-88px))]',
      )}
      style={style}
    >
      {drop.over && <DropOverlay />}
      <div
        className="flex h-10 shrink-0 cursor-pointer items-center gap-1 bg-search pr-2 pl-4 dark:bg-[#34363a]"
        onClick={() => updateWindow(win.id, { minimized: !win.minimized, maximized: false })}
      >
        <span className="min-w-0 flex-1 truncate text-sm font-medium text-fg">{title}</span>
        <IconButton icon={MdMinimize} label={win.minimized ? 'Expand' : 'Minimize'} size="sm" onClick={(e) => { e.stopPropagation(); updateWindow(win.id, { minimized: !win.minimized, maximized: false }); }} />
        <IconButton
          icon={win.maximized ? MdCloseFullscreen : MdOpenInFull}
          label={win.maximized ? 'Exit full screen' : 'Full screen'}
          size="sm"
          onClick={(e) => {
            e.stopPropagation();
            updateWindow(win.id, { maximized: !win.maximized, minimized: false });
          }}
        />
        <IconButton icon={MdClose} label="Save & close" size="sm" onClick={(e) => { e.stopPropagation(); c.close(); }} />
      </div>
      {!win.minimized && (
        <>
          {body}
          <div className="px-4 pt-1 pb-3">
            <BottomBar c={c} editor={editor} />
          </div>
        </>
      )}
    </div>
  );

  if (win.maximized) {
    return createPortal(
      <div className="fixed inset-0 z-[55] flex animate-fade items-center justify-center bg-scrim" onPointerDown={(e) => e.target === e.currentTarget && updateWindow(win.id, { maximized: false })}>
        {panel}
      </div>,
      document.body,
    );
  }
  return panel;
}

function MobileScheduleItem({ c, close }: { c: Composer; close: () => void }) {
  const [open, setOpen] = useState(false);
  return (
    <>
      <MenuItem
        icon={MdSchedule}
        label="Schedule send"
        onClick={() => {
          setOpen(true);
        }}
      />
      <ScheduleDialog
        open={open}
        onClose={() => {
          setOpen(false);
          close();
        }}
        onPick={(ts) => c.send(ts)}
      />
    </>
  );
}

function QuoteToggle({ html }: { html: string }) {
  const [open, setOpen] = useState(false);
  return (
    <div>
      <button type="button" aria-label={open ? 'Hide trimmed content' : 'Show trimmed content'} data-tip={open ? 'Hide trimmed content' : 'Show trimmed content'} onClick={() => setOpen((o) => !o)} className="flex h-4 items-center rounded-sm bg-chip px-1 text-fg2 hover:bg-hover">
        <MdMoreHoriz size={18} />
      </button>
      {open && <div className="mail-body mt-2 text-sm opacity-80" dangerouslySetInnerHTML={{ __html: html }} />}
    </div>
  );
}

export function ComposeDock() {
  const composes = useUI((s) => s.composes);
  if (!composes.length) return null;
  return (
    <div className="print-hide pointer-events-none fixed inset-x-0 bottom-0 z-[45]">
      {composes.map((w, i) => (
        <ComposeWindow key={w.id} win={w} index={i} total={composes.length} />
      ))}
    </div>
  );
}

const MODE_META: Record<ComposeMode, { icon: typeof MdReply; label: string }> = {
  new: { icon: MdReply, label: 'Reply' },
  reply: { icon: MdReply, label: 'Reply' },
  replyAll: { icon: MdReplyAll, label: 'Reply all' },
  forward: { icon: MdForward, label: 'Forward' },
};

export function InlineComposer({ threadId }: { threadId: string }) {
  const inline = useUI((s) => s.inline);
  if (!inline || inline.threadId !== threadId) return null;
  return <InlineComposerInner key={inline.key} inline={inline} />;
}

function InlineComposerInner({ inline }: { inline: NonNullable<ReturnType<typeof useUI.getState>['inline']> }) {
  const c = useComposer({
    threadId: inline.threadId,
    draftId: inline.draftId,
    mode: inline.mode,
    initial: inline.initial,
    onClosed: () => ui.set({ inline: null }),
    reopen: (fields, mode) => {
      const r = currentRoute();
      if (r.view !== 'settings' && r.threadId === inline.threadId) ui.set({ inline: { ...inline, initial: fields, mode, key: uid('ir') } });
      else reopenWindow({ threadId: inline.threadId, draftId: inline.draftId, mode, isNewThread: false, minimized: false, maximized: false, initial: fields, focus: 'body' });
    },
  });
  const editor = useRef<EditorHandle>(null);
  const [editingRecipients, setEditingRecipients] = useState(inline.mode === 'forward' || !inline.initial.to.length);
  const [showCc, setShowCc] = useState(inline.initial.cc.length > 0);
  const [modeMenu, setModeMenu] = useState<HTMLElement | null>(null);
  const drop = useDropFiles(c);
  const ref = useRef<HTMLDivElement>(null);
  const thread = useMail((s) => s.threads[inline.threadId]);
  const Meta = MODE_META[c.mode];

  useEffect(() => {
    ref.current?.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
  }, []);

  useEffect(() => {
    if (c.mode === 'forward') setEditingRecipients(true);
  }, [c.mode]);

  const multi = thread ? new Set(thread.messages.flatMap((m) => [m.from.email, ...m.to.map((x) => x.email), ...m.cc.map((x) => x.email)]).filter((e) => e !== MY_EMAIL)).size > 1 : false;

  return (
    <div
      ref={ref}
      {...drop.props}
      className="relative my-4 rounded-2xl bg-raised shadow-e2 ring-1 ring-line md:ml-[52px]"
      onKeyDown={(e) => {
        if (e.key === 'Escape') {
          e.stopPropagation();
          c.close();
        }
      }}
      data-testid="inline-composer"
    >
      {drop.over && <DropOverlay />}
      <div className="flex items-center gap-1 px-2 pt-2">
        <button type="button" onClick={(e) => setModeMenu(e.currentTarget)} className="flex h-8 items-center rounded px-1 text-fg2 hover:bg-hover" aria-label="Type of response" data-tip="Type of response">
          <Meta.icon size={18} />
          <MdArrowDropDown size={18} />
        </button>
        <Popover open={!!modeMenu} anchor={modeMenu} onClose={() => setModeMenu(null)}>
          <div className="w-56">
            <MenuItem icon={MdReply} label="Reply" onClick={() => { setModeMenu(null); c.switchMode('reply'); }} />
            {multi && <MenuItem icon={MdReplyAll} label="Reply to all" onClick={() => { setModeMenu(null); c.switchMode('replyAll'); }} />}
            <MenuItem icon={MdForward} label="Forward" onClick={() => { setModeMenu(null); c.switchMode('forward'); }} />
            <MenuItem icon={MdOpenInNew} label="Pop out reply" onClick={() => { setModeMenu(null); popOutInline(c.fields); }} />
          </div>
        </Popover>
        {!editingRecipients ? (
          <button type="button" onClick={() => setEditingRecipients(true)} className="min-w-0 flex-1 truncate rounded px-1 py-1 text-left text-sm text-fg hover:bg-hover">
            {[...c.fields.to, ...c.fields.cc].map((x) => x.name || x.email).join(', ')}
          </button>
        ) : (
          <div className="min-w-0 flex-1 pr-2">
            <RecipientField
              label="To"
              value={c.fields.to}
              onChange={(to) => c.update({ to })}
              autoFocus
              trailing={
                !showCc && (
                  <button type="button" className="ml-auto pl-2 text-sm text-fg2 hover:underline" onClick={() => setShowCc(true)}>
                    Cc
                  </button>
                )
              }
            />
            {showCc && <RecipientField label="Cc" value={c.fields.cc} onChange={(cc) => c.update({ cc })} />}
          </div>
        )}
      </div>
      <div className="px-4 pt-2">
        <RichEditor ref={editor} initialHtml={inline.initial.body} onChange={(b) => c.update({ body: b })} autoFocus={!editingRecipients} onKeyDown={sendShortcut(c)} onFiles={c.addFiles} className="min-h-[120px] pb-3" />
        {c.fields.quote && (
          <div className="pb-2">
            <QuoteToggle html={c.fields.quote} />
          </div>
        )}
        <AttachmentList c={c} />
      </div>
      <div className="px-4 pt-1 pb-3">
        <BottomBar c={c} editor={editor} onPopOut={() => popOutInline(c.fields)} />
      </div>
    </div>
  );
}

args.streamContent:
import { useEffect, useMemo, useRef, useState } from 'react';
import type { IconType } from 'react-icons';
import {
  MdArrowBack,
  MdArrowDropDown,
  MdChevronLeft,
  MdChevronRight,
  MdContentCopy,
  MdDeleteForever,
  MdDownload,
  MdForward,
  MdLabelImportant,
  MdLabelImportantOutline,
  MdLabelOutline,
  MdMoreHoriz,
  MdMoreVert,
  MdOutlineArchive,
  MdOutlineDelete,
  MdOutlineDriveFileMove,
  MdOutlineLock,
  MdOutlineMarkEmailUnread,
  MdOutlineMoveToInbox,
  MdOutlineReport,
  MdOutlineWatchLater,
  MdPersonSearch,
  MdPrint,
  MdReply,
  MdReplyAll,
  MdSchedule,
  MdSearch,
  MdSend,
  MdStar,
  MdStarBorder,
  MdUnfoldLess,
  MdUnfoldMore,
  MdVolumeOff,
  MdWarningAmber,
  MdZoomIn,
} from 'react-icons/md';
import type { Attachment, Message, Thread } from '../types';
import { useIsMobile, useNow, useThreadList } from '../hooks';
import { actions } from '../lib/actions';
import { openCompose, openReply, reopenWindow } from '../lib/composeActions';
import { fieldsFromDraft } from '../lib/compose';
import { formatFullDate, formatFuture, formatListDate, formatLongDate, relativeAgo } from '../lib/date';
import { realMessages } from '../lib/mailbox';
import { listOf, navigate, withThread, type Route } from '../lib/router';
import { highlightTerms, parseQuery } from '../lib/search';
import { cn, firstName, formatSize, htmlToText, sameEmail, stripQuote } from '../lib/utils';
import { downloadAttachment, fileKind, previewSrc } from '../lib/visuals';
import { MY_EMAIL, useMail } from '../store/mail';
import { useSettings } from '../store/settings';
import { confirmDialog, showToast, ui, useUI } from '../store/ui';
import { InlineComposer } from './compose/Composer';
import { LabelMenu, MoveMenu, SnoozeMenu } from './menus';
import { Avatar, Button, IconButton, LabelChip, MenuDivider, MenuItem, Popover, SystemChip } from './ui';

type ThreadRoute = Exclude<Route, { view: 'settings' }> & { threadId: string };

export function ThreadView({ route, embedded }: { route: ThreadRoute; embedded?: boolean }) {
  const thread = useMail((s) => s.threads[route.threadId]);
  const isMobile = useIsMobile();

  useEffect(() => {
    const id = route.threadId;
    const current = ui.get().inline;
    if (current && current.threadId !== id) ui.set({ inline: null });
    ui.set({ cursor: id });
    const t = useMail.getState().threads[id];
    if (t && !isMobile) {
      const draft = t.messages.find((m) => m.status === 'draft');
      if (draft && t.messages.some((m) => m.status !== 'draft') && ui.get().inline?.threadId !== id) openReply(id, draft.replyMode ?? 'reply');
    }
    return () => {
      if (ui.get().inline?.threadId === id) ui.set({ inline: null });
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [route.threadId]);

  const msgCount = thread?.messages.length ?? 0;
  useEffect(() => {
    if (thread?.unread) useMail.getState().patch([thread.id], (t) => ({ ...t, unread: false }));
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [route.threadId, msgCount]);

  if (!thread) {
    return (
      <div className="flex h-full flex-col">
        <div className="flex h-12 items-center px-2">
          {!embedded && <IconButton icon={MdArrowBack} label="Back" onClick={() => navigate(listOf(route))} />}
        </div>
        <div className="flex flex-1 flex-col items-center justify-center p-8 text-center text-fg3">
          <MdSearch size={48} className="text-line-strong" />
          <p className="mt-3 text-base text-fg">This conversation could not be found.</p>
          <p className="mt-1 text-sm">It may have been deleted forever.</p>
        </div>
      </div>
    );
  }
  return <ThreadContent key={thread.id} thread={thread} route={route} embedded={embedded} />;
}

function ThreadContent({ thread, route, embedded }: { thread: Thread; route: ThreadRoute; embedded?: boolean }) {
  const labels = useMail((s) => s.labels);
  const isMobile = useIsMobile();
  const inline = useUI((s) => s.inline);
  const now = useNow(30_000);
  const msgs = thread.messages.filter((m) => m.status !== 'draft');
  const [expanded, setExpanded] = useState<Set<string>>(() => {
    const s = new Set<string>();
    const last = msgs[msgs.length - 1];
    if (last) s.add(last.id);
    msgs.forEach((m) => m.status === 'scheduled' && s.add(m.id));
    return s;
  });
  const [showAll, setShowAll] = useState(msgs.length <= 4);
  const prevCount = useRef(msgs.length);
  useEffect(() => {
    if (msgs.length > prevCount.current) {
      const newest = msgs[msgs.length - 1];
      setExpanded((s) => new Set([...s, newest.id]));
    }
    prevCount.current = msgs.length;
  }, [msgs]);

  const highlight = route.view === 'search' ? highlightTerms(parseQuery(route.query)) : [];
  const threadLabels = thread.labelIds.map((id) => labels.find((l) => l.id === id)).filter((l): l is NonNullable<typeof l> => !!l);
  const inlineActive = inline?.threadId === thread.id;
  const participants = new Set(msgs.flatMap((m) => [m.from.email, ...m.to.map((x) => x.email), ...m.cc.map((x) => x.email)]).filter((e) => !sameEmail(e, MY_EMAIL)));
  const allExpanded = msgs.every((m) => expanded.has(m.id));

  const toggle = (id: string) =>
    setExpanded((s) => {
      const n = new Set(s);
      if (n.has(id)) n.delete(id);
      else n.add(id);
      return n;
    });

  const visible: Array<Message | 'gap'> = showAll || msgs.length <= 4 ? msgs : [msgs[0], 'gap', ...msgs.slice(-2)];
  const hiddenCount = msgs.length - 3;
  const onlyScheduled = msgs.length > 0 && msgs.every((m) => m.status === 'scheduled');

  return (
    <div className="print-only-thread flex h-full min-h-0 flex-col" data-testid="thread-view">
      <ThreadToolbar thread={thread} route={route} embedded={embedded} allExpanded={allExpanded} onToggleAll={() => {
        if (allExpanded) setExpanded(new Set([msgs[msgs.length - 1]?.id].filter(Boolean) as string[]));
        else {
          setShowAll(true);
          setExpanded(new Set(msgs.map((m) => m.id)));
        }
      }} />
      <div className="min-h-0 flex-1 overflow-y-auto" id="thread-scroll">
        <div className={cn('mx-auto pb-24 md:pb-10', embedded ? 'px-4' : 'px-4 md:pr-6 md:pl-[72px]')}>
          <div className="flex items-start gap-3 pt-4 pb-3 md:pt-5 md:pl-[52px]">
            <h2 className="min-w-0 flex-1 text-xl leading-7 text-fg md:text-[22px]" data-testid="thread-subject">
              <span className="mr-2">{thread.subject || '(no subject)'}</span>
              {thread.important && <MdLabelImportant size={20} className="mr-2 inline align-[-3px] text-star" aria-label="Important" />}
              <span className="inline-flex flex-wrap items-center gap-1.5 align-[3px]">
                {thread.inInbox && !thread.trashed && !thread.spam && <SystemChip text="Inbox" onRemove={() => actions.archive([thread.id])} />}
                {thread.trashed && <SystemChip text="Trash" onRemove={() => actions.moveToInbox([thread.id])} />}
                {thread.spam && <SystemChip text="Spam" onRemove={() => actions.notSpam([thread.id])} />}
                {threadLabels.map((l) => (
                  <LabelChip key={l.id} label={l} size="md" onRemove={() => actions.applyLabels([thread.id], [], [l.id])} onClick={() => navigate({ view: 'label', labelId: l.id })} />
                ))}
              </span>
            </h2>
            {!isMobile && <IconButton icon={MdPrint} label="Print all" onClick={() => window.print()} />}
          </div>

          {thread.spam && (
            <Banner tone="danger" icon={MdWarningAmber} title="Why is this message in spam?" action={<Button variant="outlined" onClick={() => actions.notSpam([thread.id])}>Report not spam</Button>}>
              It is similar to messages that were identified as spam in the past. Be careful with links and never share your password.
            </Banner>
          )}
          {thread.muted && (
            <Banner tone="info" icon={MdVolumeOff} title="This conversation is muted." action={<Button variant="text" onClick={() => actions.unmute([thread.id])}>Unmute</Button>}>
              New messages in this conversation will skip your inbox.
            </Banner>
          )}

          {visible.map((m, i) =>
            m === 'gap' ? (
              <button
                key="gap"
                type="button"
                onClick={() => setShowAll(true)}
                className="group relative my-1 flex h-6 w-full items-center md:pl-0"
                aria-label={`Show ${hiddenCount} older messages`}
              >
                <span className="absolute inset-x-0 top-1/2 border-t border-line" />
                <span className="absolute inset-x-0 top-[calc(50%+4px)] border-t border-line" />
                <span className="relative z-[1] ml-0 flex size-10 items-center justify-center rounded-full border border-line bg-panel text-sm font-medium text-fg2 group-hover:bg-hover">{hiddenCount}</span>
              </button>
            ) : (
              <MessageItem
                key={m.id}
                m={m}
                thread={thread}
                expanded={expanded.has(m.id)}
                onToggle={() => toggle(m.id)}
                canCollapse={msgs.length > 1}
                first={i === 0}
                highlight={highlight}
                now={now}
                participantsCount={participants.size}
              />
            ),
          )}

          <InlineComposer threadId={thread.id} />

          {!inlineActive && !onlyScheduled && msgs.length > 0 && (
            <div className="print-hide flex flex-wrap gap-2 pt-4 pb-6 md:gap-3 md:pl-[52px]">
              <ReplyButton icon={MdReply} label="Reply" onClick={() => openReply(thread.id, 'reply')} />
              {participants.size > 1 && <ReplyButton icon={MdReplyAll} label="Reply all" onClick={() => openReply(thread.id, 'replyAll')} />}
              <ReplyButton icon={MdForward} label="Forward" onClick={() => openReply(thread.id, 'forward')} />
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

function ReplyButton({ icon: Icon, label, onClick }: { icon: IconType; label: string; onClick: () => void }) {
  return (
    <button type="button" onClick={onClick} className="flex h-10 items-center gap-2 rounded-full border border-line-strong pr-5 pl-4 text-sm font-medium text-fg2 hover:bg-hover">
      <Icon size={18} /> {label}
    </button>
  );
}

function Banner({ tone, icon: Icon, title, children, action }: { tone: 'danger' | 'info'; icon: IconType; title: string; children: React.ReactNode; action?: React.ReactNode }) {
  return (
    <div className={cn('mb-4 flex flex-wrap items-start gap-3 rounded-xl p-4 md:ml-[52px]', tone === 'danger' ? 'bg-[#fce8e6] text-[#5f2120] dark:bg-[#4a1f1c] dark:text-[#f6d3cf]' : 'bg-chip text-fg2')}>
      <Icon size={22} className="shrink-0" />
      <div className="min-w-[200px] flex-1 text-sm">
        <div className="font-medium">{title}</div>
        <div className="mt-0.5 opacity-90">{children}</div>
      </div>
      {action}
    </div>
  );
}

function ToolbarMenu({ icon, label, kind, render, disabled }: { icon: IconType; label: string; kind?: 'labels' | 'move' | 'snooze'; render: (close: () => void) => React.ReactNode; disabled?: boolean }) {
  const ref = useRef<HTMLButtonElement>(null);
  const [open, setOpen] = useState(false);
  const req = useUI((s) => s.menuRequest);
  useEffect(() => {
    if (req && kind && req.kind === kind) {
      setOpen(true);
      ui.set({ menuRequest: null });
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [req]);
  return (
    <>
      <IconButton ref={ref} icon={icon} label={label} onClick={() => setOpen((o) => !o)} active={open} disabled={disabled} />
      <Popover open={open} anchor={ref.current} onClose={() => setOpen(false)}>
        {render(() => setOpen(false))}
      </Popover>
    </>
  );
}

function ThreadToolbar({ thread, route, embedded, allExpanded, onToggleAll }: { thread: Thread; route: ThreadRoute; embedded?: boolean; allExpanded: boolean; onToggleAll: () => void }) {
  const list = useThreadList(listOf(route));
  const isMobile = useIsMobile();
  const [more, setMore] = useState<HTMLElement | null>(null);
  const [mobileMode, setMobileMode] = useState<'main' | 'move' | 'labels' | 'snooze'>('main');
  const idx = list.findIndex((t) => t.id === thread.id);
  const newer = idx > 0 ? list[idx - 1] : null;
  const older = idx >= 0 && idx < list.length - 1 ? list[idx + 1] : null;
  const ids = [thread.id];
  const back = () => navigate(listOf(route));
  const lastSender = realMessages(thread).at(-1)?.from;

  const moreItems = (close: () => void) => (
    <div className="w-64">
      {isMobile && mobileMode === 'main' && (
        <>
          <MenuItem icon={MdOutlineDriveFileMove} label="Move to" onClick={() => setMobileMode('move')} />
          <MenuItem icon={MdLabelOutline} label="Change labels" onClick={() => setMobileMode('labels')} />
          <MenuItem icon={MdOutlineWatchLater} label="Snooze" onClick={() => setMobileMode('snooze')} />
          <MenuItem icon={thread.starred ? MdStarBorder : MdStar} label={thread.starred ? 'Remove star' : 'Add star'} onClick={() => { close(); actions.star(ids, !thread.starred); }} />
          <MenuItem icon={MdOutlineReport} label="Report spam" onClick={() => { close(); actions.spam(ids); }} />
          <MenuDivider />
        </>
      )}
      {(!isMobile || mobileMode === 'main') && (
        <>
          <MenuItem icon={thread.important ? MdLabelImportantOutline : MdLabelImportant} label={thread.important ? 'Mark as not important' : 'Mark as important'} onClick={() => { close(); actions.important(ids, !thread.important); }} />
          <MenuItem icon={MdVolumeOff} label={thread.muted ? 'Unmute' : 'Mute'} onClick={() => { close(); (thread.muted ? actions.unmute : actions.mute)(ids); }} />
          <MenuItem icon={allExpanded ? MdUnfoldLess : MdUnfoldMore} label={allExpanded ? 'Collapse all' : 'Expand all'} onClick={() => { close(); onToggleAll(); }} />
          <MenuItem icon={MdPrint} label="Print all" onClick={() => { close(); setTimeout(() => window.print(), 50); }} />
          {lastSender && (
            <MenuItem icon={MdPersonSearch} label="Filter messages like these" onClick={() => { close(); navigate({ view: 'search', query: `from:${lastSender.email}` }); }} />
          )}
        </>
      )}
      {isMobile && mobileMode === 'move' && <MoveMenu ids={ids} onClose={close} />}
      {isMobile && mobileMode === 'labels' && <LabelMenu ids={ids} onClose={close} />}
      {isMobile && mobileMode === 'snooze' && <SnoozeMenu ids={ids} onClose={close} />}
    </div>
  );

  const closeMore = () => {
    setMore(null);
    setMobileMode('main');
  };

  if (isMobile) {
    return (
      <div className="print-hide flex h-14 shrink-0 items-center gap-0.5 px-1" role="toolbar" aria-label="Conversation actions">
        <IconButton icon={MdArrowBack} label="Back" onClick={back} />
        <div className="flex-1" />
        {thread.trashed ? (
          <IconButton icon={MdOutlineMoveToInbox} label="Move to Inbox" onClick={() => actions.moveToInbox(ids)} />
        ) : thread.inInbox ? (
          <IconButton icon={MdOutlineArchive} label="Archive" onClick={() => actions.archive(ids)} />
        ) : (
          <IconButton icon={MdOutlineMoveToInbox} label="Move to Inbox" onClick={() => actions.moveToInbox(ids)} />
        )}
        <IconButton icon={thread.trashed ? MdDeleteForever : MdOutlineDelete} label="Delete" onClick={() => (thread.trashed ? actions.deleteForever(ids) : actions.trash(ids))} />
        <IconButton icon={MdOutlineMarkEmailUnread} label="Mark as unread" onClick={() => actions.markRead(ids, false, { leave: true })} />
        <IconButton icon={MdMoreVert} label="More" onClick={(e) => setMore(e.currentTarget)} />
        <Popover open={!!more} anchor={more} onClose={closeMore} placement="bottom-end">
          {moreItems(closeMore)}
        </Popover>
      </div>
    );
  }

  return (
    <div className="print-hide flex h-12 shrink-0 items-center gap-0.5 px-2 md:pl-3" role="toolbar" aria-label="Conversation actions">
      {!embedded && <IconButton icon={MdArrowBack} label={`Back to ${route.view === 'search' ? 'Search results' : 'list'}`} onClick={back} />}
      {thread.trashed ? (
        <>
          <IconButton icon={MdOutlineMoveToInbox} label="Move to Inbox" onClick={() => actions.moveToInbox(ids)} />
          <IconButton icon={MdDeleteForever} label="Delete forever" onClick={() => actions.deleteForever(ids)} />
        </>
      ) : thread.spam ? (
        <>
          <button type="button" onClick={() => actions.notSpam(ids)} className="h-8 rounded px-3 text-sm font-medium text-fg2 hover:bg-hover">
            Not spam
          </button>
          <IconButton icon={MdDeleteForever} label="Delete forever" onClick={() => actions.deleteForever(ids)} />
        </>
      ) : (
        <>
          {thread.inInbox ? (
            <IconButton icon={MdOutlineArchive} label="Archive" onClick={() => actions.archive(ids)} />
          ) : (
            <IconButton icon={MdOutlineMoveToInbox} label="Move to Inbox" onClick={() => actions.moveToInbox(ids)} />
          )}
          <IconButton icon={MdOutlineReport} label="Report spam" onClick={() => actions.spam(ids)} />
          <IconButton icon={MdOutlineDelete} label="Delete" onClick={() => actions.trash(ids)} />
        </>
      )}
      <span className="mx-1.5 h-5 w-px bg-line" />
      <IconButton icon={MdOutlineMarkEmailUnread} label="Mark as unread" onClick={() => actions.markRead(ids, false, { leave: true })} />
      {thread.snoozedUntil ? (
        <IconButton icon={MdOutlineWatchLater} label="Unsnooze" onClick={() => actions.unsnooze(ids)} />
      ) : (
        <ToolbarMenu icon={MdOutlineWatchLater} label="Snooze" kind="snooze" render={(close) => <SnoozeMenu ids={ids} onClose={close} />} disabled={thread.trashed || thread.spam} />
      )}
      <span className="mx-1.5 h-5 w-px bg-line" />
      <ToolbarMenu icon={MdOutlineDriveFileMove} label="Move to" kind="move" render={(close) => <MoveMenu ids={ids} onClose={close} />} />
      <ToolbarMenu icon={MdLabelOutline} label="Labels" kind="labels" render={(close) => <LabelMenu ids={ids} onClose={close} />} />
      <IconButton icon={MdMoreVert} label="More" onClick={(e) => setMore(e.currentTarget)} />
      <Popover open={!!more} anchor={more} onClose={closeMore}>
        {moreItems(closeMore)}
      </Popover>
      <div className="ml-auto flex items-center gap-1 text-xs text-fg2">
        {idx >= 0 && (
          <span className="px-2 whitespace-nowrap">
            {idx + 1} of {list.length}
          </span>
        )}
        <IconButton icon={MdChevronLeft} label="Newer" size="sm" disabled={!newer} onClick={() => newer && navigate(withThread(listOf(route), newer.id))} />
        <IconButton icon={MdChevronRight} label="Older" size="sm" disabled={!older} onClick={() => older && navigate(withThread(listOf(route), older.id))} />
      </div>
    </div>
  );
}

function highlightHtml(html: string, terms: string[]): string {
  if (!terms.length) return html;
  const tpl = document.createElement('template');
  tpl.innerHTML = html;
  const re = new RegExp(`(${terms.map((w) => w.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')).join('|')})`, 'gi');
  const walker = document.createTreeWalker(tpl.content, NodeFilter.SHOW_TEXT);
  const nodes: Text[] = [];
  while (walker.nextNode()) nodes.push(walker.currentNode as Text);
  for (const node of nodes) {
    const text = node.nodeValue ?? '';
    if (!re.test(text)) continue;
    re.lastIndex = 0;
    const frag = document.createDocumentFragment();
    text.split(re).forEach((part, i) => {
      if (i % 2 === 1) {
        const mark = document.createElement('mark');
        mark.textContent = part;
        frag.appendChild(mark);
      } else if (part) frag.appendChild(document.createTextNode(part));
    });
    node.replaceWith(frag);
  }
  return tpl.innerHTML;
}

function recipientSummary(m: Message): string {
  const all = [...m.to, ...m.cc];
  if (!all.length) return 'undisclosed recipients';
  return all.map((p) => (sameEmail(p, MY_EMAIL) ? 'me' : firstName(p.name || p.email))).slice(0, 4).join(', ') + (all.length > 4 ? ` +${all.length - 4}` : '');
}

function MessageItem({
  m,
  thread,
  expanded,
  onToggle,
  canCollapse,
  first,
  highlight,
  now,
  participantsCount,
}: {
  m: Message;
  thread: Thread;
  expanded: boolean;
  onToggle: () => void;
  canCollapse: boolean;
  first: boolean;
  highlight: string[];
  now: number;
  participantsCount: number;
}) {
  const [showQuote, setShowQuote] = useState(false);
  const [details, setDetails] = useState<HTMLElement | null>(null);
  const [more, setMore] = useState<HTMLElement | null>(null);
  const [card, setCard] = useState<HTMLElement | null>(null);
  const displayName = useSettings((s) => s.displayName);
  const contacts = useMail((s) => s.contacts);
  const unsubscribed = useMail((s) => s.unsubscribed);
  const fromMe = sameEmail(m.from, MY_EMAIL);
  const name = fromMe ? displayName || m.from.name : m.from.name || m.from.email;
  const contact = contacts.find((c) => sameEmail(c, m.from));
  const isOrg = contact?.kind === 'org' || /no-?reply|notifications|deals|hello@|store@|weekly@|brief@|team@|trips@|issue@/i.test(m.from.email);
  const body = useMemo(() => highlightHtml(stripQuote(m.body), highlight), [m.body, highlight]);
  const scheduled = m.status === 'scheduled';

  const onBodyClick = (e: React.MouseEvent) => {
    const a = (e.target as HTMLElement).closest('a');
    if (!a) return;
    e.preventDefault();
    const href = a.getAttribute('href') ?? '';
    if (!href || href.startsWith('#')) {
      showToast('Links in sample emails don’t go anywhere in this offline demo.');
      return;
    }
    if (href.startsWith('mailto:')) {
      openCompose({ to: [{ name: '', email: href.slice(7).split('?')[0] }] });
      return;
    }
    window.open(href, '_blank', 'noopener,noreferrer');
  };

  if (!expanded) {
    return (
      <div role="button" tabIndex={0} onClick={onToggle} onKeyDown={(e) => e.key === 'Enter' && onToggle()} className={cn('flex cursor-pointer items-center gap-3 py-3', !first && 'border-t border-line')} data-testid="message-collapsed">
        <Avatar person={m.from} size={40} />
        <div className="min-w-0 flex-1">
          <div className="flex items-baseline gap-2">
            <span className="truncate text-sm font-bold text-fg">{name}</span>
            {scheduled && <span className="text-xs font-medium text-danger">Scheduled</span>}
          </div>
          <div className="truncate text-sm text-fg3">{htmlToText(stripQuote(m.body)).slice(0, 200)}</div>
        </div>
        <span className="shrink-0 text-xs text-fg3">
          {formatListDate(m.date, now)}
          <span className="hidden sm:inline"> ({relativeAgo(m.date, now)})</span>
        </span>
      </div>
    );
  }

  const openDetails = (e: React.MouseEvent<HTMLElement>) => {
    e.stopPropagation();
    setDetails(e.currentTarget);
  };

  return (
    <article className={cn('py-4', !first && 'border-t border-line')} data-testid="message-expanded">
      <div className="flex gap-3">
        <button type="button" onClick={(e) => setCard(e.currentTarget)} aria-label={`About ${name}`} className="shrink-0 self-start rounded-full">
          <Avatar person={m.from} size={40} />
        </button>
        <div className="min-w-0 flex-1">
          <div className="flex items-start gap-2">
            <div className={cn('min-w-0 flex-1', canCollapse && 'cursor-pointer')} onClick={() => canCollapse && onToggle()}>
              <div className="flex flex-wrap items-baseline gap-x-1.5">
                <button type="button" onClick={(e) => { e.stopPropagation(); setCard(e.currentTarget); }} className="text-sm font-bold text-fg hover:underline">
                  {name}
                </button>
                <span className="truncate text-xs text-fg3">&lt;{m.from.email}&gt;</span>
                {isOrg && !fromMe && (
                  unsubscribed.includes(m.from.email.toLowerCase()) ? (
                    <span className="text-xs text-fg3">· Unsubscribed</span>
                  ) : (
                    <button
                      type="button"
                      className="text-xs text-fg2 underline hover:text-fg"
                      onClick={(e) => {
                        e.stopPropagation();
                        confirmDialog({
                          title: `Unsubscribe from ${m.from.name}?`,
                          message: `Future messages from ${m.from.email} will stop arriving in this demo mailbox.`,
                          confirmLabel: 'Unsubscribe',
                          onConfirm: () => {
                            useMail.getState().unsubscribe(m.from.email);
                            showToast(`Unsubscribed from ${m.from.name}.`);
                          },
                        });
                      }}
                    >
                      Unsubscribe
                    </button>
