              if (draft) {
                reopenWindow({ threadId: thread.id, draftId: m.id, mode: 'new', isNewThread: t!.messages.every((x) => x.status === 'draft'), minimized: false, maximized: false, initial: fieldsFromDraft(draft, t!.subject), focus: 'body' });
