+  if (!all.length) return 'undisclosed recipients';
+  return all.map((p) => (sameEmail(p, MY_EMAIL) ? 'me' : firstName(p.name || p.email))).slice(0, 4).join(', ') + (all.length > 4 ? ` +${all.length - 4}` : '');
+}
