+          <Avatar person={m.from} size={40} />
+        </button>
+        <div className="min-w-0 flex-1">
+          <div className="flex items-start gap-2">
+            <div className={cn('min-w-0 flex-1', canCollapse && 'cursor-pointer')} onClick={() => canCollapse && onToggle()}>
