+              const draft = t?.messages.find((x) => x.id === m.id);
+              if (draft) {
+                reopenWindow({ threadId: thread.id, draftId: m.id, mode: 'new', isNewThread: t!.messages.every((x) => x.status === 'draft'), minimized: false, maximized: false, initial: fieldsFromDraft(draft, t!.subject), focus: 'body' });
+              }
+              showToast('Send canceled. Your message is back in Drafts.');
+            }}
+          >
+            Cancel send
+          </Button>
+          <Button
+            variant="text"
+            onClick={() => {
+              useMail.getState().patch([thread.id], (t) => ({ ...t, messages: t.messages.map((x) => (x.id === m.id ? { ...x, status: 'sent', date: Date.now(), scheduledAt: undefined } : x)) }));
+              showToast('Message sent.');
+            }}
+          >
+            <MdSend size={16} /> Send now
+          </Button>
+        </div>
+      )}
+
+      <div className="mt-3 md:pl-[52px]" data-testid="message-body">
