          </div>
        </div>
        <div className="flex gap-2 border-t border-line px-4 py-3">
          {!fromMe && (
            <Button variant="tonal" className="h-8 px-4" onClick={() => { setCard(null); openCompose({ to: [m.from] }); }}>
              Send email
