  );
}

function AttachmentGrid({ atts }: { atts: Attachment[] }) {
  return (
    <div className="mt-4 border-t border-line pt-3 md:ml-[52px]" data-testid="attachments">
      <div className="mb-3 flex items-center gap-2 text-sm text-fg2">
