import type { ComposeMode, DraftFields, Message, Person, Thread } from '../types';
import { formatFullDate, formatLongDate } from './date';
import { realMessages } from './mailbox';
import { escapeHtml, sameEmail, stripQuote } from './utils';

export function buildQuote(m: Message): string {
  return `<div class="mail-quote"><p>On ${formatFullDate(m.date)}, ${escapeHtml(m.from.name || m.from.email)} &lt;${escapeHtml(m.from.email)}&gt; wrote:</p><blockquote>${stripQuote(m.body)}</blockquote></div>`;
}

export function signatureHtml(sig: string): string {
  return sig.trim() ? `<div class="signature">-- <br>${sig}</div>` : '';
}

export function emptyBody(sig: string): string {
  const s = signatureHtml(sig);
  return s ? `<div><br></div><div><br></div>${s}` : '';
}

export function prefixSubject(prefix: 'Re' | 'Fwd', subject: string): string {
  const re = new RegExp(`^${prefix}:\\s*`, 'i');
  const s = subject.trim() || '(no subject)';
  return re.test(s) ? s : `${prefix}: ${s}`;
}

function dedupe(list: Person[], exclude: string[]): Person[] {
  const out: Person[] = [];
  for (const p of list) {
    if (exclude.some((e) => sameEmail(e, p))) continue;
    if (out.some((o) => sameEmail(o, p))) continue;
    out.push(p);
  }
  return out;
}

export function forwardBlock(m: Message, subject: string): string {
  const to = m.to.map((p) => `${escapeHtml(p.name)} &lt;${escapeHtml(p.email)}&gt;`).join(', ');
  return `<div class="forwarded"><div>---------- Forwarded message ---------</div><div>From: <b>${escapeHtml(m.from.name)}</b> &lt;${escapeHtml(m.from.email)}&gt;</div><div>Date: ${formatLongDate(m.date)}</div><div>Subject: ${escapeHtml(subject)}</div><div>To: ${to}</div><br>${stripQuote(m.body)}</div>`;
}

export function replyFields(t: Thread, mode: ComposeMode, meEmail: string, signature: string, source?: Message): DraftFields {
  const real = realMessages(t);
  const src = source ?? real[real.length - 1] ?? t.messages[t.messages.length - 1];
  const fromMe = sameEmail(src.from, meEmail);
  if (mode === 'forward') {
    const block = forwardBlock(src, t.subject);
    return {
      to: [],
      cc: [],
      bcc: [],
      subject: prefixSubject('Fwd', t.subject),
      body: `<div><br></div>${signatureHtml(signature)}<div><br></div>${block}`,
      attachments: src.attachments.map((a) => ({ ...a })),
    };
  }
  let to: Person[];
  let cc: Person[] = [];
  if (mode === 'reply') {
    to = fromMe ? src.to : [src.from];
  } else {
    to = fromMe ? src.to : dedupe([src.from, ...src.to], [meEmail]);
    cc = dedupe(src.cc, [meEmail, ...to.map((p) => p.email)]);
  }
  return {
    to: dedupe(to, fromMe ? [] : [meEmail]),
    cc,
    bcc: [],
    subject: prefixSubject('Re', t.subject),
    body: emptyBody(signature),
    quote: buildQuote(src),
    attachments: [],
  };
}

export function fieldsFromDraft(m: Message, subject: string): DraftFields {
  return { to: m.to, cc: m.cc, bcc: m.bcc, subject, body: m.body, quote: m.quote, attachments: m.attachments };
}

export function isEmptyDraft(f: DraftFields, signature: string): boolean {
  const bodyText = f.body
    .replace(/<div class="signature">[\s\S]*?<\/div>/, '')
    .replace(/<[^>]+>/g, '')
    .replace(/&nbsp;/g, '')
    .trim();
  const sigOnly = !bodyText || f.body === emptyBody(signature);
  return !f.to.length && !f.cc.length && !f.bcc.length && !f.subject.trim() && sigOnly && !f.attachments.length;
}

export function parseAddress(raw: string): Person | null {
  const s = raw.trim().replace(/[,;]+$/, '');
  if (!s) return null;
  const m = s.match(/^\s*"?([^"<]*?)"?\s*<([^>]+)>\s*$/);
  if (m) return { name: m[1].trim(), email: m[2].trim() };
  return { name: '', email: s };
}

import { create } from 'zustand';
import type { Attachment, ComposeMode, DraftFields } from '../types';

export interface ComposeWin {
  id: string;
  threadId: string;
  draftId: string;
  mode: ComposeMode;
  isNewThread: boolean;
  minimized: boolean;
  maximized: boolean;
  initial: DraftFields;
  focus?: 'to' | 'body' | 'subject';
}

export interface InlineReply {
  threadId: string;
  draftId: string;
  mode: ComposeMode;
  initial: DraftFields;
  key: string;
}

export interface Toast {
  id: number;
  message: string;
  undo?: () => void;
  action?: { label: string; run: () => void };
  duration?: number;
}

export interface ConfirmState {
  title?: string;
  message: string;
  confirmLabel: string;
  cancelLabel?: string;
  danger?: boolean;
  alertOnly?: boolean;
  onConfirm: () => void;
}

export type MenuKind = 'labels' | 'move' | 'snooze';

export interface UIState {
  selected: string[];
  anchor: string | null;
  cursor: string | null;
  page: number;
  drawerOpen: boolean;
  composes: ComposeWin[];
  inline: InlineReply | null;
  toast: Toast | null;
  quickSettings: boolean;
  shortcutsOpen: boolean;
  labelDialog: { labelId?: string; applyTo?: string[] } | null;
  confirm: ConfirmState | null;
  preview: { attachments: Attachment[]; index: number } | null;
  menuRequest: { kind: MenuKind; nonce: number } | null;
  searchFocus: number;
  advancedSearch: boolean;
  refreshing: boolean;
  mobileSearch: boolean;
  frozen: { key: string; ids: string[] } | null;
}

export const useUI = create<UIState>()(() => ({
  selected: [],
  anchor: null,
  cursor: null,
  page: 0,
  drawerOpen: false,
  composes: [],
  inline: null,
  toast: null,
  quickSettings: false,
  shortcutsOpen: false,
  labelDialog: null,
  confirm: null,
  preview: null,
  menuRequest: null,
  searchFocus: 0,
  advancedSearch: false,
  refreshing: false,
  mobileSearch: false,
  frozen: null,
}));

export const ui = {
  set: useUI.setState,
  get: useUI.getState,
};

let toastSeq = 0;
export function showToast(message: string, opts: Omit<Toast, 'id' | 'message'> = {}) {
  ui.set({ toast: { id: ++toastSeq, message, ...opts } });
}

export function hideToast() {
  ui.set({ toast: null });
}

export function confirmDialog(c: ConfirmState) {
  ui.set({ confirm: c });
}

export function clearSelection() {
  ui.set({ selected: [], anchor: null });
}

import type { ComposeMode, DraftFields, Person, Thread } from '../types';
import { isMobileNow } from '../hooks';
import { MY_EMAIL, useMail } from '../store/mail';
import { useSettings } from '../store/settings';
import { showToast, ui, type ComposeWin } from '../store/ui';
import { emptyBody, fieldsFromDraft, isEmptyDraft, replyFields } from './compose';
import { formatFuture } from './date';
import { navigate } from './router';
import { uid } from './utils';

export function me(): Person {
  return { name: useSettings.getState().displayName || 'Alex Rivera', email: MY_EMAIL };
}

function pushWindow(win: ComposeWin) {
  const { composes } = ui.get();
  const existing = composes.find((c) => c.draftId === win.draftId);
  if (existing) {
    ui.set({ composes: composes.map((c) => (c.id === existing.id ? { ...c, minimized: false } : c)) });
    return;
  }
  let next = [...composes.map((c) => ({ ...c, maximized: false })), win];
  if (next.length > 3) next = next.slice(-3);
  ui.set({ composes: next, drawerOpen: false });
}

export function openCompose(initial: Partial<DraftFields> = {}) {
  const sig = useSettings.getState().signature;
  const fields: DraftFields = { to: [], cc: [], bcc: [], subject: '', body: emptyBody(sig), attachments: [], ...initial };
  pushWindow({
    id: uid('cw'),
    threadId: uid('t'),
    draftId: uid('m'),
    mode: 'new',
    isNewThread: true,
    minimized: false,
    maximized: false,
    initial: fields,
    focus: fields.to.length ? (fields.subject ? 'body' : 'subject') : 'to',
  });
}

export function openDraft(thread: Thread) {
  const draft = thread.messages.find((m) => m.status === 'draft');
  if (!draft) return;
  const onlyDrafts = thread.messages.every((m) => m.status === 'draft');
  if (onlyDrafts || isMobileNow()) {
    pushWindow({
      id: uid('cw'),
      threadId: thread.id,
      draftId: draft.id,
      mode: draft.replyMode ?? 'new',
      isNewThread: onlyDrafts,
      minimized: false,
      maximized: false,
      initial: fieldsFromDraft(draft, onlyDrafts ? thread.subject : draft.replyMode === 'forward' ? `Fwd: ${thread.subject}` : `Re: ${thread.subject}`),
      focus: 'body',
    });
    return;
  }
  navigate({ view: 'folder', folder: 'drafts', threadId: thread.id });
}

export function openReply(threadId: string, mode: ComposeMode, sourceMessageId?: string) {
  const t = useMail.getState().threads[threadId];
  if (!t) return;
  const settings = useSettings.getState();
  const existing = t.messages.find((m) => m.status === 'draft');
  const source = sourceMessageId ? t.messages.find((m) => m.id === sourceMessageId) : undefined;
  const draftId = existing?.id ?? uid('m');
  const fields = existing && !source ? fieldsFromDraft(existing, existing.replyMode === 'forward' ? `Fwd: ${t.subject}` : `Re: ${t.subject}`) : replyFields(t, mode, MY_EMAIL, settings.signature, source);
  const effectiveMode = existing && !source ? (existing.replyMode ?? mode) : mode;
  if (isMobileNow()) {
    pushWindow({ id: uid('cw'), threadId, draftId, mode: effectiveMode, isNewThread: false, minimized: false, maximized: false, initial: fields, focus: mode === 'forward' ? 'to' : 'body' });
    return;
  }
  ui.set({ inline: { threadId, draftId, mode: effectiveMode, initial: fields, key: uid('ir') } });
}

export function popOutInline(fields: DraftFields) {
  const inline = ui.get().inline;
  if (!inline) return;
  ui.set({ inline: null });
  pushWindow({ id: uid('cw'), threadId: inline.threadId, draftId: inline.draftId, mode: inline.mode, isNewThread: false, minimized: false, maximized: false, initial: fields, focus: 'body' });
}

export function closeWindow(id: string) {
  ui.set({ composes: ui.get().composes.filter((c) => c.id !== id) });
}

export function updateWindow(id: string, patch: Partial<ComposeWin>) {
  ui.set({ composes: ui.get().composes.map((c) => (c.id === id ? { ...c, ...patch } : c)) });
}

export function saveDraftNow(threadId: string, draftId: string, fields: DraftFields, mode: ComposeMode) {
  const sig = useSettings.getState().signature;
  const mail = useMail.getState();
  const exists = mail.threads[threadId]?.messages.some((m) => m.id === draftId);
