export function MenuDivider() {
  return <div className="my-1.5 h-px bg-line" />;
}

export function MenuHeading({ children }: { children: ReactNode }) {
  return <div className="px-4 pt-1 pb-2 text-xs font-medium tracking-wide text-fg3">{children}</div>;
}

export function Modal({
  open,
  onClose,
  children,
  className,
  label,
}: {
  open: boolean;
  onClose: () => void;
  children: ReactNode;
  className?: string;
  label: string;
}) {
  const closeRef = useRef(onClose);
  closeRef.current = onClose;
  useEffect(() => {
    if (!open) return;
    const onKey = (e: KeyboardEvent) => {
      if (e.key === 'Escape') {
        e.stopPropagation();
        closeRef.current();
      }
    };
    document.addEventListener('keydown', onKey, true);
    return () => document.removeEventListener('keydown', onKey, true);
  }, [open]);
  if (!open) return null;
  return createPortal(
    <div
      className="fixed inset-0 z-[70] flex items-center justify-center bg-scrim p-4 animate-fade"
      onPointerDown={(e) => {
        e.stopPropagation();
        if (e.target === e.currentTarget) onClose();
      }}
      onClick={(e) => e.stopPropagation()}
      onKeyDown={(e) => e.stopPropagation()}
    >
      <div role="dialog" aria-modal="true" aria-label={label} className={cn('max-h-full w-full animate-pop overflow-auto rounded-2xl bg-raised text-fg shadow-e2', className)}>
        {children}
      </div>
    </div>,
    document.body,
  );
}

export function Checkbox({
  checked,
  indeterminate,
  onChange,
  label,
  className,
}: {
  checked: boolean;
  indeterminate?: boolean;
  onChange: (e: React.MouseEvent) => void;
  label: string;
  className?: string;
}) {
  const Icon = indeterminate ? MdIndeterminateCheckBox : checked ? MdCheckBox : MdCheckBoxOutlineBlank;
  return (
    <button
      type="button"
      role="checkbox"
      aria-checked={indeterminate ? 'mixed' : checked}
      aria-label={label}
      onClick={(e) => {
        e.stopPropagation();
        onChange(e);
      }}
      className={cn('inline-flex size-8 shrink-0 items-center justify-center rounded-full hover:bg-hover', checked || indeterminate ? 'text-fg' : 'text-fg3', className)}
    >
      <Icon size={20} />
    </button>
  );
}

export function Avatar({ person, size = 40, className }: { person: Person; size?: number; className?: string }) {
  const myColor = useSettings((s) => s.avatarColor);
  const myName = useSettings((s) => s.displayName);
  const isMe = sameEmail(person, MY_EMAIL);
  const name = isMe ? myName || person.name : person.name || person.email;
  const bg = isMe ? myColor : avatarColor(person.email);
  return (
    <span
      aria-hidden
      className={cn('inline-flex shrink-0 select-none items-center justify-center rounded-full font-medium text-white', className)}
      style={{ width: size, height: size, background: bg, fontSize: size * 0.45 }}
    >
      {initials(name)}
    </span>
  );
}

export function useLabelStyle(label: Label): React.CSSProperties {
  const dark = useResolvedDark();
  const c = LABEL_COLORS[label.color] ?? LABEL_COLORS.gray;
  const [bg, fg] = dark ? c.dark : c.light;
  return { background: bg, color: fg };
}

export function LabelChip({ label, onRemove, size = 'sm', onClick }: { label: Label; onRemove?: () => void; size?: 'sm' | 'md'; onClick?: () => void }) {
  const style = useLabelStyle(label);
  return (
    <span
      className={cn(
        'group/chip inline-flex max-w-[160px] shrink-0 items-center rounded font-medium leading-none',
        size === 'sm' ? 'h-[18px] px-1.5 text-[11px]' : 'h-6 px-2 text-xs',
        onClick && 'cursor-pointer',
      )}
      style={style}
      onClick={
        onClick &&
        ((e) => {
          e.stopPropagation();
          onClick();
        })
      }
    >
      <span className="truncate">{label.name}</span>
      {onRemove && (
        <button
          type="button"
          aria-label={`Remove label ${label.name}`}
          data-tip={`Remove label "${label.name}"`}
          className="-mr-1 ml-1 inline-flex size-4 items-center justify-center rounded-sm opacity-60 hover:bg-black/10 hover:opacity-100"
          onClick={(e) => {
            e.stopPropagation();
            onRemove();
          }}
        >
          <MdClose size={12} />
        </button>
      )}
    </span>
  );
}

export function SystemChip({ text, onRemove }: { text: string; onRemove?: () => void }) {
  return (
    <span className="inline-flex h-6 shrink-0 items-center rounded bg-chip px-2 text-xs font-medium text-fg2">
      {text}
      {onRemove && (
        <button
          type="button"
          aria-label={`Remove ${text}`}
          data-tip={`Remove label "${text}"`}
          className="-mr-1 ml-1 inline-flex size-4 items-center justify-center rounded-sm opacity-60 hover:bg-hover hover:opacity-100"
          onClick={onRemove}
        >
          <MdClose size={12} />
        </button>
      )}
    </span>
  );
}

export function Spinner({ size = 20, className }: { size?: number; className?: string }) {
  return (
    <span
      className={cn('inline-block rounded-full border-2 border-accent border-t-transparent', className)}
      style={{ width: size, height: size, animation: 'spin 0.8s linear infinite' }}
    />
  );
}

export function Radio({ checked, onChange, label, description }: { checked: boolean; onChange: () => void; label: ReactNode; description?: ReactNode }) {
  return (
    <label className="flex cursor-pointer items-start gap-3 rounded-lg py-1.5">
      <input type="radio" className="sr-only" checked={checked} onChange={onChange} />
      <span className={cn('mt-0.5 flex size-5 shrink-0 items-center justify-center rounded-full border-2', checked ? 'border-accent' : 'border-fg3')}>
        {checked && <span className="size-2.5 rounded-full bg-accent" />}
      </span>
      <span className="min-w-0">
        <span className="block text-sm text-fg">{label}</span>
        {description && <span className="block text-xs text-fg3">{description}</span>}
      </span>
    </label>
  );
}

export function Toggle({ checked, onChange, label }: { checked: boolean; onChange: (v: boolean) => void; label: string }) {
  return (
    <button
      type="button"
      role="switch"
      aria-checked={checked}
      aria-label={label}
      onClick={() => onChange(!checked)}
      className={cn('relative inline-flex h-6 w-10 shrink-0 items-center rounded-full border-2 transition-colors', checked ? 'border-accent bg-accent' : 'border-fg3 bg-transparent')}
    >
      <span className={cn('absolute rounded-full transition-all', checked ? 'left-[18px] size-4 bg-accent-fg' : 'left-1 size-3 bg-fg3')} />
    </button>
  );
}

export function Button({
  children,
  variant = 'filled',
  className,
  ...rest
}: { variant?: 'filled' | 'tonal' | 'outlined' | 'text' | 'danger' } & React.ButtonHTMLAttributes<HTMLButtonElement>) {
  return (
    <button
      type="button"
      className={cn(
        'inline-flex h-9 items-center justify-center gap-2 rounded-full px-5 text-sm font-medium transition-[background,box-shadow] disabled:opacity-40',
        variant === 'filled' && 'bg-accent text-accent-fg hover:shadow-e1',
        variant === 'danger' && 'bg-danger text-white hover:shadow-e1 dark:text-[#1f1f1f]',
        variant === 'tonal' && 'bg-accent-soft text-fg hover:shadow-e1',
        variant === 'outlined' && 'border border-line-strong text-accent-text hover:bg-hover',
        variant === 'text' && 'px-3 text-accent-text hover:bg-hover',
        className,
      )}
      {...rest}
    >
      {children}
    </button>
  );
}

import { create } from 'zustand';
import { persist } from 'zustand/middleware';
import type { Category } from '../types';
import type { InboxType } from '../lib/mailbox';

export type Theme = 'light' | 'dark' | 'system';
export type Density = 'default' | 'comfortable' | 'compact';
export type ReadingPane = 'none' | 'right' | 'below';
export type SwipeAction = 'archive' | 'trash' | 'read' | 'star' | 'none';

export interface Settings {
  theme: Theme;
  density: Density;
  readingPane: ReadingPane;
  paneSize: number;
  inboxType: InboxType;
  categories: Exclude<Category, 'primary'>[];
  pageSize: number;
  undoSeconds: number;
  shortcuts: boolean;
  hoverActions: boolean;
  importanceMarkers: boolean;
  snippets: boolean;
  autoAdvance: 'list' | 'newer' | 'older';
  defaultReply: 'reply' | 'replyAll';
  signature: string;
  displayName: string;
  avatarColor: string;
  simulateActivity: boolean;
  swipeLeft: SwipeAction;
  swipeRight: SwipeAction;
  sidebarCollapsed: boolean;
  recentSearches: string[];
}

export const DEFAULT_SETTINGS: Settings = {
  theme: 'system',
  density: 'default',
  readingPane: 'none',
  paneSize: 42,
  inboxType: 'default',
  categories: ['promotions', 'social', 'updates'],
  pageSize: 50,
  undoSeconds: 10,
  shortcuts: true,
  hoverActions: true,
  importanceMarkers: true,
  snippets: true,
  autoAdvance: 'list',
  defaultReply: 'reply',
  signature: 'Alex Rivera<br>Product Design Lead · Lumen Labs',
  displayName: 'Alex Rivera',
  avatarColor: '#7b3fa0',
  simulateActivity: true,
  swipeLeft: 'archive',
  swipeRight: 'archive',
  sidebarCollapsed: false,
  recentSearches: [],
};

interface SettingsStore extends Settings {
  update: (patch: Partial<Settings>) => void;
  addRecentSearch: (q: string) => void;
  resetSettings: () => void;
}

export const useSettings = create<SettingsStore>()(
  persist(
    (set) => ({
      ...DEFAULT_SETTINGS,
      update: (patch) => set(patch),
      addRecentSearch: (q) =>
        set((s) => ({ recentSearches: [q, ...s.recentSearches.filter((x) => x !== q)].slice(0, 6) })),
      resetSettings: () => set(DEFAULT_SETTINGS),
    }),
    { name: 'opus-mail-settings', version: 1 },
  ),
);

import type { Category, Thread } from '../types';
import { getListContext } from '../hooks';
import { useMail } from '../store/mail';
import { useSettings } from '../store/settings';
import { clearSelection, confirmDialog, showToast, ui } from '../store/ui';
import { formatFuture } from './date';
import { CATEGORY_NAMES, computeList, inFolder } from './mailbox';
import { currentRoute, listOf, navigate, withThread, type Route } from './router';

type Mut = (t: Thread) => Thread;

const conv = (n: number) => (n === 1 ? 'Conversation' : `${n} conversations`);

function neighborRoute(route: Route, openId: string): Route {
  const mode = useSettings.getState().autoAdvance;
  const list = computeList(useMail.getState().threads, listOf(route), getListContext());
  const idx = list.findIndex((t) => t.id === openId);
  const base = listOf(route);
  if (idx === -1 || mode === 'list') return base;
  const target = mode === 'newer' ? list[idx - 1] : list[idx + 1];
  return target ? withThread(base, target.id) : base;
}

function run(ids: string[], mutate: Mut, message: string | null, opts: { forceLeave?: boolean } = {}) {
  if (!ids.length) return;
  const mail = useMail.getState();
  const route = currentRoute();
  const openId = route.view !== 'settings' ? route.threadId : undefined;
  const affectsOpen = !!openId && ids.includes(openId);
  const next = affectsOpen ? neighborRoute(route, openId!) : null;
  const snap = mail.snapshot(ids);
  mail.patch(ids, mutate);
  clearSelection();
  let left = false;
  if (affectsOpen) {
    const after = computeList(useMail.getState().threads, listOf(route), getListContext());
    if (opts.forceLeave || !after.some((t) => t.id === openId)) {
      navigate(next!);
      left = true;
    }
  }
  if (message) {
    showToast(message, {
      undo: () => {
        useMail.getState().restore(snap);
        if (left) navigate(route);
      },
    });
  }
}

export const actions = {
  archive(ids: string[]) {
    run(ids, (t) => ({ ...t, inInbox: false, snoozedUntil: null }), `${conv(ids.length)} archived.`);
  },
  trash(ids: string[]) {
    run(ids, (t) => ({ ...t, trashed: true }), `${conv(ids.length)} moved to Trash.`);
  },
  moveToInbox(ids: string[]) {
    run(ids, (t) => ({ ...t, trashed: false, spam: false, inInbox: true, snoozedUntil: null }), `${conv(ids.length)} moved to Inbox.`);
  },
  spam(ids: string[]) {
    run(ids, (t) => ({ ...t, spam: true, inInbox: false, snoozedUntil: null }), `${conv(ids.length)} marked as spam.`);
  },
  notSpam(ids: string[]) {
    run(ids, (t) => ({ ...t, spam: false, inInbox: true }), `${conv(ids.length)} unmarked as spam and moved to Inbox.`);
  },
  markRead(ids: string[], read: boolean, opts: { leave?: boolean } = {}) {
    run(ids, (t) => ({ ...t, unread: !read }), ids.length > 1 ? `${conv(ids.length)} marked as ${read ? 'read' : 'unread'}.` : null, { forceLeave: opts.leave });
  },
  star(ids: string[], starred: boolean) {
    useMail.getState().patch(ids, (t) => ({ ...t, starred }));
    if (ids.length > 1) showToast(`${conv(ids.length)} ${starred ? 'starred' : 'unstarred'}.`);
  },
  important(ids: string[], important: boolean) {
    run(ids, (t) => ({ ...t, important }), `${conv(ids.length)} marked as ${important ? 'important' : 'not important'}.`);
  },
  snooze(ids: string[], until: number) {
    run(ids, (t) => ({ ...t, snoozedUntil: until, inInbox: true }), `Snoozed until ${formatFuture(until)}`);
  },
  unsnooze(ids: string[]) {
    run(ids, (t) => ({ ...t, snoozedUntil: null, inInbox: true }), `${conv(ids.length)} unsnoozed.`);
  },
  mute(ids: string[]) {
    run(ids, (t) => ({ ...t, muted: true, inInbox: false }), `${conv(ids.length)} muted.`);
  },
  unmute(ids: string[]) {
    run(ids, (t) => ({ ...t, muted: false }), `${conv(ids.length)} unmuted.`);
  },
  applyLabels(ids: string[], add: string[], remove: string[]) {
    const labels = useMail.getState().labels;
    const name = (id: string) => labels.find((l) => l.id === id)?.name ?? '';
    const msg =
      add.length === 1 && !remove.length
        ? `${conv(ids.length)} added to "${name(add[0])}".`
        : remove.length === 1 && !add.length
          ? `${conv(ids.length)} removed from "${name(remove[0])}".`
          : 'Labels updated.';
    run(ids, (t) => ({ ...t, labelIds: [...new Set([...t.labelIds.filter((l) => !remove.includes(l)), ...add])] }), msg);
  },
  moveTo(ids: string[], target: { kind: 'inbox' | 'spam' | 'trash' } | { kind: 'label'; id: string } | { kind: 'category'; id: Category }) {
    if (target.kind === 'inbox') return actions.moveToInbox(ids);
    if (target.kind === 'spam') return actions.spam(ids);
    if (target.kind === 'trash') return actions.trash(ids);
    const route = currentRoute();
    if (target.kind === 'category') {
      run(ids, (t) => ({ ...t, category: target.id, inInbox: true, trashed: false }), `${conv(ids.length)} moved to "${CATEGORY_NAMES[target.id]}".`);
      return;
    }
    const label = useMail.getState().labels.find((l) => l.id === target.id);
    run(
      ids,
      (t) => {
        let labelIds = [...new Set([...t.labelIds, target.id])];
        if (route.view === 'label' && route.labelId !== target.id) labelIds = labelIds.filter((l) => l !== route.labelId);
        return { ...t, labelIds, inInbox: false, trashed: false, spam: false };
      },
      `${conv(ids.length)} moved to "${label?.name}".`,
    );
  },
  deleteForever(ids: string[]) {
    confirmDialog({
      title: 'Delete forever?',
      message: `${ids.length === 1 ? 'This conversation' : `These ${ids.length} conversations`} will be permanently deleted. You can undo right after.`,
      confirmLabel: 'Delete forever',
      danger: true,
      onConfirm: () => {
        const mail = useMail.getState();
        const snap = mail.snapshot(ids);
        const route = currentRoute();
        mail.remove(ids);
        clearSelection();
        if (route.view !== 'settings' && route.threadId && ids.includes(route.threadId)) navigate(listOf(route));
        showToast(`${conv(ids.length)} deleted forever.`, { undo: () => useMail.getState().restore(snap) });
      },
    });
  },
  emptyFolder(folder: 'trash' | 'spam') {
    const now = Date.now();
    const ids = Object.values(useMail.getState().threads)
      .filter((t) => inFolder(t, folder, now))
      .map((t) => t.id);
    if (!ids.length) return;
    confirmDialog({
      title: folder === 'trash' ? 'Empty Trash?' : 'Delete all spam?',
      message: `This will permanently delete ${ids.length} conversation${ids.length === 1 ? '' : 's'}.`,
      confirmLabel: 'OK',
      danger: true,
      onConfirm: () => {
        const mail = useMail.getState();
        const snap = mail.snapshot(ids);
        mail.remove(ids);
        clearSelection();
        showToast(`${conv(ids.length)} deleted forever.`, { undo: () => useMail.getState().restore(snap) });
      },
    });
  },
  discardDrafts(ids: string[]) {
    const mail = useMail.getState();
    const snap = mail.snapshot(ids);
    const route = currentRoute();
    for (const id of ids) {
      const t = mail.threads[id];
      t?.messages.filter((m) => m.status === 'draft').forEach((m) => useMail.getState().discardDraft(id, m.id));
    }
    clearSelection();
    if (route.view !== 'settings' && route.threadId && ids.includes(route.threadId) && !useMail.getState().threads[route.threadId]) navigate(listOf(route));
    showToast(ids.length === 1 ? 'Draft discarded.' : `${ids.length} drafts discarded.`, { undo: () => useMail.getState().restore(snap) });
  },
  cancelScheduled(ids: string[]) {
    const mail = useMail.getState();
    const snap = mail.snapshot(ids);
    for (const id of ids) {
      mail.threads[id]?.messages.filter((m) => m.status === 'scheduled').forEach((m) => useMail.getState().unschedule(id, m.id));
    }
    clearSelection();
    showToast('Send canceled. Moved to Drafts.', { undo: () => useMail.getState().restore(snap) });
  },
  refresh() {
    if (ui.get().refreshing) return;
    ui.set({ refreshing: true });
    setTimeout(() => {
      if (useSettings.getState().simulateActivity) useMail.getState().deliverNext(Date.now());
      ui.set({ refreshing: false });
    }, 650);
  },
};

