            ).map(([k, l]) => (
              <Radio key={k} checked={s.inboxType === k} onChange={() => s.update({ inboxType: k })} label={l} />
            ))}
          </Section>
          <Section title="Reading pane">
            {(
              [
                ['none', 'No split'],
                ['right', 'Right of inbox'],
                ['below', 'Below inbox'],
              ] as Array<[ReadingPane, string]>
            ).map(([k, l]) => (
              <Radio key={k} checked={s.readingPane === k} onChange={() => s.update({ readingPane: k })} label={l} />
            ))}
          </Section>
          <Section title="Mailbox">
            <label className="flex items-center justify-between gap-3 py-1.5 text-sm text-fg">
              Simulate new mail
              <input type="checkbox" className="size-4 accent-[var(--c-accent)]" checked={s.simulateActivity} onChange={(e) => s.update({ simulateActivity: e.target.checked })} />
            </label>
            <label className="flex items-center justify-between gap-3 py-1.5 text-sm text-fg">
              Keyboard shortcuts
              <input type="checkbox" className="size-4 accent-[var(--c-accent)]" checked={s.shortcuts} onChange={(e) => s.update({ shortcuts: e.target.checked })} />
