  --color-scrim: var(--scrim);
  --shadow-e1: var(--shadow-1);
  --shadow-e2: var(--shadow-2);
  --shadow-e3: var(--shadow-3);
  --shadow-row: var(--shadow-row);
  --animate-pop: pop 140ms cubic-bezier(0.2, 0, 0, 1);
  --animate-fade: fade 160ms ease-out;
  --animate-slide-up: slide-up 220ms cubic-bezier(0.2, 0, 0, 1);
  --animate-slide-left: slide-left 220ms cubic-bezier(0.2, 0, 0, 1);
  --animate-slide-right: slide-right 240ms cubic-bezier(0.2, 0, 0, 1);
}

@keyframes pop {
  from { opacity: 0; transform: scale(0.96) translateY(-4px); }
  to { opacity: 1; transform: none; }
}
@keyframes fade {
  from { opacity: 0; }
  to { opacity: 1; }
}
@keyframes slide-up {
  from { opacity: 0; transform: translateY(16px); }
  to { opacity: 1; transform: none; }
}
@keyframes slide-left {
  from { transform: translateX(100%); }
  to { transform: none; }
}
@keyframes slide-right {
  from { transform: translateX(-100%); }
  to { transform: none; }
}
@keyframes spin {
  to { transform: rotate(360deg); }
}
@keyframes arrive {
  from { background-color: var(--accent-soft); }
}

html,
body,
#root {
  height: 100%;
}

body {
  margin: 0;
  background: var(--bg);
  color: var(--fg);
  font-family: var(--font-sans);
  font-size: 14px;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  overscroll-behavior: none;
}

button {
  cursor: pointer;
}

button:disabled {
  cursor: default;
}

:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: -2px;
}

* {
  scrollbar-width: thin;
  scrollbar-color: var(--line-strong) transparent;
}

::selection {
  background: #c2dbff;
}

.dark ::selection {
  background: #3b5998;
}

.row-arrive {
  animation: arrive 2.4s ease-out;
}

/* Message bodies */
.mail-body {
  font-size: 14px;
  line-height: 1.55;
  color: var(--fg);
  overflow-wrap: anywhere;
}
.mail-body p {
  margin: 0 0 0.85em;
}
.mail-body p:last-child {
  margin-bottom: 0;
}
.mail-body a {
  color: var(--accent-text);
}
.mail-body ul,
.mail-body ol {
  margin: 0 0 0.85em;
  padding-left: 1.6em;
}
.mail-body ul {
  list-style: disc;
}
.mail-body ol {
  list-style: decimal;
}
.mail-body li {
  margin: 0.15em 0;
}
.mail-body blockquote {
  margin: 0.5em 0 0.5em 0.4em;
  padding-left: 0.9em;
  border-left: 2px solid var(--line-strong);
  color: var(--quote);
}
.mail-body pre,
.mail-body code {
  font-family: ui-monospace, "SF Mono", Menlo, monospace;
  font-size: 12.5px;
}
.mail-body pre {
  background: var(--chip);
  border-radius: 8px;
  padding: 10px 12px;
  overflow-x: auto;
  margin: 0 0 0.85em;
}
.mail-body code {
  background: var(--chip);
  padding: 1px 4px;
  border-radius: 4px;
}
.mail-body pre code {
  background: none;
  padding: 0;
}
.mail-body h1,
.mail-body h2,
.mail-body h3 {
  font-weight: 500;
  margin: 0 0 0.5em;
}
.mail-body table {
  border-collapse: collapse;
}
.mail-body img {
  max-width: 100%;
}
.mail-body .signature {
  color: var(--fg3);
}
.mail-body mark,
.mail-hl {
  background: #fde293;
  color: #1f1f1f;
  border-radius: 2px;
}
.mail-body .html-email {
  color: #1f1f1f;
}

/* Rich editor */
.editor {
  outline: none;
  line-height: 1.5;
  overflow-wrap: anywhere;
}
.editor:empty::before {
  content: attr(data-placeholder);
  color: var(--fg3);
  pointer-events: none;
}
.editor p {
  margin: 0;
}
.editor ul {
  list-style: disc;
  padding-left: 1.6em;
}
.editor ol {
  list-style: decimal;
  padding-left: 1.6em;
}
.editor blockquote {
  margin: 0 0 0 0.4em;
  padding-left: 0.9em;
  border-left: 2px solid var(--line-strong);
  color: var(--quote);
}
.editor a {
  color: var(--accent-text);
  text-decoration: underline;
}
.editor .signature {
  color: var(--fg3);
}

.no-scrollbar {
  scrollbar-width: none;
}
.no-scrollbar::-webkit-scrollbar {
  display: none;
}

@media print {
  body {
    background: #fff;
  }
  .print-hide {
    display: none !important;
  }
  .print-only-thread {
    position: static !important;
    overflow: visible !important;
    height: auto !important;
  }
}

