.editor {
  outline: none;
  line-height: 1.5;
  overflow-wrap: anywhere;
}
.editor:empty::before {
  content: attr(data-placeholder);
  color: var(--fg3);
  pointer-events: none;
}
.editor p {
  margin: 0;
}
.editor ul {
  list-style: disc;
  padding-left: 1.6em;
}
.editor ol {
  list-style: decimal;
  padding-left: 1.6em;
}
.editor blockquote {
  margin: 0 0 0 0.4em;
  padding-left: 0.9em;
  border-left: 2px solid var(--line-strong);
  color: var(--quote);
}
.editor a {
  color: var(--accent-text);
  text-decoration: underline;
}
.editor .signature {
  color: var(--fg3);
}

.no-scrollbar {
  scrollbar-width: none;
}
.no-scrollbar::-webkit-scrollbar {
  display: none;
}

@media print {
  html,
  body,
  #root {
    height: auto !important;
    background: #fff !important;
  }
  .print-hide {
    display: none !important;
  }
  .print-flow,
  .print-flow * {
    overflow: visible !important;
    height: auto !important;
    max-height: none !important;
    min-height: 0 !important;
  }
  .print-only-thread {
    position: static !important;
    overflow: visible !important;
    height: auto !important;
  }
}

