          handled();
          openCompose();
          return;
        case '/':
          handled();
          ui.set({ searchFocus: Date.now() });
          return;
        case '?':
          handled();
          ui.set({ shortcutsOpen: true });
          return;
        case 'j':
        case 'ArrowDown':
          if (key === 'ArrowDown' && openId) return;
          handled();
          moveCursor(1);
          return;
        case 'k':
        case 'ArrowUp':
