          const star = !targets.every((id) => threads[id]?.starred);
          actions.star(targets, star);
          return;
        }
        case 'e':
          if (!targets.length) return;
          handled();
          actions.archive(targets);
          return;
        case '#':
          if (!targets.length) return;
          handled();
          if (targets.every(inTrash)) actions.deleteForever(targets);
          else actions.trash(targets);
          return;
        case '!':
          if (!targets.length) return;
          handled();
          actions.spam(targets);
          return;
        case 'I':
          if (!targets.length) return;
          handled();
          actions.markRead(targets, true);
          return;
        case 'U':
          if (!targets.length) return;
          handled();
          actions.markRead(targets, false, { leave: !!openId && !state.selected.length });
          return;
        case '+':
        case '=':
          if (!targets.length) return;
          handled();
          actions.important(targets, true);
          return;
        case '-':
          if (!targets.length) return;
          handled();
          actions.important(targets, false);
          return;
        case 'm':
          if (!targets.length) return;
          handled();
          actions.mute(targets);
          return;
        case 'r':
          handled();
          reply(useSettings.getState().defaultReply === 'replyAll' ? 'replyAll' : 'reply');
          return;
        case 'R':
          handled();
          reply('reply');
          return;
        case 'a':
          handled();
          reply('replyAll');
          return;
        case 'f':
          handled();
          reply('forward');
          return;
        case 'l':
          handled();
          requestMenu('labels');
          return;
        case 'v':
          handled();
          requestMenu('move');
          return;
        case 'b':
          handled();
          requestMenu('snooze');
          return;
        case '[':
          handled();
          archiveAndGo(-1);
          return;
        case ']':
          handled();
          archiveAndGo(1);
          return;
        case 'z': {
          const t = ui.get().toast;
          if (!t?.undo) return;
          handled();
          const undo = t.undo;
          hideToast();
          undo();
          showToast('Action undone.');
          return;
        }
        case 'g':
        case '*':
          handled();
          prefix = { key, at: Date.now() };
          return;
      }
    };

    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, []);
}

