      run: () => navigate({ view: 'folder', folder: p.scheduledAt ? 'scheduled' : 'sent', threadId: p.threadId }),
    },
  });
}

export function reopenWindow(win: Omit<ComposeWin, 'id'>) {
  pushWindow({ ...win, id: uid('cw'), minimized: false });
}

