          <LabelNavItem key={l.id} label={l} expanded={expanded} active={route.view === 'label' && route.labelId === l.id} count={counts.labels[l.id]} onClick={() => go({ view: 'label', labelId: l.id })} />
        ))}

      {mobile && (
        <>
          <div className="mx-5 my-3 h-px bg-line" />
