  await page.waitForSelector('[role="dialog"][aria-label="Keyboard shortcuts"]');
  await page.screenshot({ path: OUT + '10-shortcuts.png' });
  await page.keyboard.press('Escape');
});

await step('snooze via hover action menu', async () => {
