const results = [];
const errors = [];
let failures = 0;

async function step(name, fn) {
  try {
    await fn();
    results.push(`PASS  ${name}`);
  } catch (e) {
    failures++;
    results.push(`FAIL  ${name}\n      ${String(e?.message ?? e).split('\n').slice(0, 4).join('\n      ')}`);
