});

await browser.close();

console.log(results.join('\n'));
console.log(`\n${results.length - failures}/${results.length} passed`);
if (errors.length) {
  console.log('\nBrowser errors:');
  for (const e of [...new Set(errors)].slice(0, 30)) console.log('  ' + e);
}
process.exit(failures ? 1 : 0);

