export const RichEditor = forwardRef<
  EditorHandle,
  { initialHtml: string; onChange: (html: string) => void; placeholder?: string; autoFocus?: boolean; className?: string; onKeyDown?: (e: React.KeyboardEvent) => void; onFiles?: (files: File[]) => void }
>(function RichEditor({ initialHtml, onChange, placeholder, autoFocus, className, onKeyDown, onFiles }, ref) {
  const el = useRef<HTMLDivElement>(null);
  const saved = useRef<Range | null>(null);
  const changeRef = useRef(onChange);
  changeRef.current = onChange;

  const emit = useCallback(() => {
    if (el.current) changeRef.current(el.current.innerHTML);
  }, []);

  useEffect(() => {
    if (!el.current) return;
    el.current.innerHTML = initialHtml;
    if (autoFocus) {
      el.current.focus();
      const r = document.createRange();
      r.setStart(el.current, 0);
      r.collapse(true);
      const sel = window.getSelection();
      sel?.removeAllRanges();
      sel?.addRange(r);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  useImperativeHandle(ref, () => ({
    focus: (atEnd) => {
      const node = el.current;
      if (!node) return;
      node.focus();
      if (atEnd) {
        const r = document.createRange();
        r.selectNodeContents(node);
        r.collapse(false);
        const sel = window.getSelection();
        sel?.removeAllRanges();
        sel?.addRange(r);
      }
    },
    exec: (cmd, value) => {
      el.current?.focus();
      document.execCommand(cmd, false, value);
      emit();
    },
    insertHtml: (html) => {
      el.current?.focus();
      if (saved.current) {
        const sel = window.getSelection();
        sel?.removeAllRanges();
        sel?.addRange(saved.current);
      }
      document.execCommand('insertHTML', false, html);
      emit();
    },
    saveSelection: () => {
      const sel = window.getSelection();
      if (sel && sel.rangeCount && el.current?.contains(sel.anchorNode)) saved.current = sel.getRangeAt(0).cloneRange();
    },
    restoreSelection: () => {
      el.current?.focus();
      if (saved.current) {
        const sel = window.getSelection();
        sel?.removeAllRanges();
        sel?.addRange(saved.current);
      }
    },
    getHtml: () => el.current?.innerHTML ?? '',
    el: () => el.current,
  }));

  return (
    <div
      ref={el}
      role="textbox"
      aria-multiline="true"
      aria-label="Message body"
      contentEditable
      suppressContentEditableWarning
      data-placeholder={placeholder}
      className={cn('editor text-sm text-fg', className)}
      onInput={emit}
      onKeyDown={onKeyDown}
      onPaste={(e) => {
        const files = Array.from(e.clipboardData.files);
        if (files.length && onFiles) {
          e.preventDefault();
          onFiles(files);
          return;
        }
        const html = e.clipboardData.getData('text/html');
        const text = e.clipboardData.getData('text/plain');
        e.preventDefault();
        if (html) document.execCommand('insertHTML', false, sanitizeHtml(html));
        else document.execCommand('insertText', false, text);
        emit();
      }}
    />
  );
});

