                onClick={(e) => {
                  e.stopPropagation();
                  onChange(value.filter((v) => v !== p));
                }}
              >
                <MdClose size={14} />
              </button>
            </span>
          );
        })}
        <input
          ref={inputRef}
          id={inputId}
          value={input}
          onChange={(e) => {
