              }}
              className={cn(
                'inline-flex h-7 max-w-full items-center gap-1.5 rounded-full border py-0.5 pr-1 pl-0.5 text-sm',
                invalid ? 'border-danger bg-danger/10 text-danger' : 'border-line-strong text-fg',
