              {(folder === 'trash' || folder === 'spam') && (
                <MenuItem icon={MdDeleteForever} label={folder === 'trash' ? 'Empty Trash' : 'Delete all spam'} onClick={() => { setMoreMenu(null); actions.emptyFolder(folder); }} />
